(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c45"]=[{"id":"00005796","register_sub_id":"101","register_pk":"106784","name":"高澤家住宅主屋","kana":"たかざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県行田市長野3-5-41","lat":36.139561,"lng":139.473282,"geo_status":"db","era":"江戸末期／明治期・昭和期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積303㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"11 － 0102","desc":"敷地中央北寄りに位置し，南面して建つ。桁行１１間，梁間６間半規模，木造２階建，切妻造，桟瓦葺とする。１階は出入口から南北に土間を通し，その東側に板の間，西側に畳部屋６室を配し，２階は蚕室を設ける。越屋根や両妻面の高窓が養蚕民家の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005796"},{"id":"00006011","register_sub_id":"101","register_pk":"106996","name":"高澤家住宅土蔵","kana":"たかざわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県行田市長野3-5-41","lat":36.139717,"lng":139.473282,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造及び木造平屋建、鉄板葺、建築面積37㎡","structure_material":"土蔵造及び木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"11 － 0104","desc":"主屋の北方に位置し，南面して建つ。桁行２間半，梁間２間規模の土蔵造平屋建で，切妻造，鉄板葺とする。正面に桟瓦葺の下屋を付け，上方に窓を開き，東方に２間半四方の木造平屋建，切妻造，鉄板葺の蔵が附属する。外壁は漆喰塗で，全体に簡素なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006011"},{"id":"00006013","register_sub_id":"101","register_pk":"106998","name":"高澤家住宅長屋門","kana":"たかざわけじゅうたくながやもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県行田市長野3-5-41","lat":36.139282,"lng":139.473511,"geo_status":"db","era":"安政6／昭和50頃改修","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造、瓦葺、間口5.5m","structure_material":"木造","registered":"2007.05.15(平成19.05.15)","register_no":"11 － 0106","desc":"敷地の南方に位置し，南面して建つ。間口・奥行共５．５ｍで，切妻造，桟瓦葺とする。乳金物を飾った両開板扉を吊り込み，東脇に潜戸を設ける。両側の平屋建物置は火災により改築しているが，中央の門は残り，その規模等から往時の豪壮な表構えが伝えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006013"},{"id":"00006012","register_sub_id":"101","register_pk":"106997","name":"高澤家住宅納屋","kana":"たかざわけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県行田市長野3-5-41","lat":36.139549,"lng":139.473648,"geo_status":"db","era":"明治3頃","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"11 － 0105","desc":"敷地の東方に位置し，西面して建つ。桁行５間半，梁間３間，木造つし２階建，平入の切妻造，桟瓦葺とし，北側及び西側に下屋を廻す。１階は土間，２階は蚕室とし，外壁は真壁造で南妻面及び東面に換気用の高窓を開く。養蚕農家の建物として特徴ある外観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006012"},{"id":"00006015","register_sub_id":"101","register_pk":"107000","name":"高澤家住宅離れ","kana":"たかざわけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県行田市長野3-5-41","lat":36.13953,"lng":139.473068,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積126㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"11 － 0103","desc":"主屋の北西方に位置する。桁行７間，梁間３間規模，木造平屋建，桟瓦形の鉄板葺で，西側を寄棟造，東側を切妻造とする。奉公人の増加により主人用に増築したもので，８畳の床の間付の座敷３室を並べ，北東方に板の間を附属する。豪農の敷地景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006015"},{"id":"00013776","register_sub_id":"101","register_pk":"507691","name":"田島亀夫家住宅主屋","kana":"たじまかめおけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県本庄市宮戸字西浦650-3","lat":36.24593611,"lng":139.23799722,"geo_status":"db","era":"明治2年頃／明治初期増築","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造2階建、瓦葺、建築面積286㎡","structure_material":"木造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"11 － 0204","desc":"田島弥平旧宅（国史跡）の近隣に建つ蚕種を製造した民家。桁行一二間梁間五間の総二階建の背面に下屋が付属する。屋根は切妻造桟瓦葺で、棟に三箇所越屋根を備える。内部は大床や付書院を備えた座敷を構える。明治初期の姿を残す島村地区最大級の養蚕住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013776"},{"id":"00014137","register_sub_id":"101","register_pk":"508767","name":"田島亀夫家住宅蚕室","kana":"たじまかめおけじゅうたくさんしつ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県本庄市宮戸字西浦650-3","lat":36.24570556,"lng":139.23812222,"geo_status":"db","era":"明治後期／昭和中期・同50年頃・令和2年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"11-0215","desc":"島村の利根川南岸に所在する農家の蚕室。敷地南の表門東脇に位置する。二階建、切妻造桟瓦葺で換気の越屋根を二つ備え、北面に土庇を設ける。当初は真壁造腰板壁の外壁で、一階は貯桑場、二階は窓を連ねて開放的な上蔟室として用いた。専用蚕室として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014137"},{"id":"00013507","register_sub_id":"101","register_pk":"504871","name":"田中家長屋","kana":"たなかけながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県比企郡小川町大字小川字上町177","lat":36.05404167,"lng":139.26111667,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積188㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"11 － 0197","desc":"小川町は八王子道と秩父道が交差する交通の要衝で、和紙生産でも知られる。木造二階建切妻造鉄板葺で、道なりに屈曲した平面をもつ。一、二階とも腰下見板張上部漆喰塗。小屋は二重梁和小屋。もと六軒長屋でうち五軒分が残る。町の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013507"},{"id":"00004523","register_sub_id":"101","register_pk":"105513","name":"所沢郷土美術館主屋","kana":"ところざわきょうどびじゅつかんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県所沢市大字久米1447-1","lat":35.78007742,"lng":139.46441052,"geo_status":"db","era":"安政元","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積184㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"11 － 0086","desc":"敷地西寄りに東面して建つ。木造平屋建，南北棟，入母屋造，銅板葺で，所沢市内に残る稀少な近世住宅遺構のひとつ。式台玄関から奥の間に至る接客空間の意匠は，川越松平藩の侍医を務めた医家の格式を伝える。普請覚帳から棟梁は打越村大工・新左衛門が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004523"},{"id":"00004525","register_sub_id":"101","register_pk":"105515","name":"所沢郷土美術館土蔵","kana":"ところざわきょうどびじゅつかんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県所沢市大字久米1447-1","lat":35.78011466,"lng":139.46465214,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"11 － 0088","desc":"敷地東側，長屋門の北側に建つ。東西棟，切妻造，桟瓦葺，妻入の２階建土蔵で，西面に入口を設けて庇を掛け，２階に窓を開ける。外壁を白漆喰で仕上げ，開口部を黒漆喰で飾り，軒に鉢巻を廻す。長屋門とともに屋敷地の表構えを構成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004525"},{"id":"00004524","register_sub_id":"101","register_pk":"105514","name":"所沢郷土美術館長屋門","kana":"ところざわきょうどびじゅつかんながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県所沢市大字久米1447-1","lat":35.78003625,"lng":139.46465214,"geo_status":"db","era":"安政2","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"11 － 0087","desc":"敷地東端に道路より後退して南北棟で建つ。木造平屋建，入母屋造桟瓦葺。中央に門口を開き，左右に同規模の部屋を配す。建物南端に１室張出し，切妻屋根を架ける。外壁は漆喰塗で腰を下見板張とする。棟梁は主屋と同じ。屋敷構えに欠くことのできない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004524"},{"id":"00016362","register_sub_id":"101","register_pk":"536429","name":"冨田家住宅離れ","kana":"とみたけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和中","pref":"埼玉県","address":"埼玉県羽生市南三丁目236","lat":36.16845,"lng":139.53893333,"geo_status":"db","era":"昭和27年／昭和49年増築","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造2階建、瓦葺、建築面積123㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"11 - 0240","desc":"市街地の中心部に位置する旧染物店の離れ座敷。二階建切妻造桟瓦葺で、南面東寄りに入母屋造玄関を突出し、西に階段室などを増築する。南庭に面して各階3室の続き間座敷を配し、二階中の間と小脇に、下地窓を蔓枝で菱組にするなど全体に凝ったつくりの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016362"},{"id":"00012698","register_sub_id":"101","register_pk":"367601","name":"永瀬孝男家住宅表門及び煉瓦塀","kana":"ながせたかおけじゅうたくおもてもんおよびれんがべい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県川口市本町一丁目21-1","lat":35.79779278,"lng":139.72454194,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"門 石造、間口2.9ｍ 塀 煉瓦造、延長75m","structure_material":"門 石造","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 184","desc":"敷地東面南寄りに開く門と敷地の東面と北面を区切る塀。門は切石の組積造風で、モルタル洗出し仕上の門柱を間口3・6メートルで立てる。塀は高さ2・7メートルのイギリス積で、二段の蛇腹上に桟瓦葺の屋根を載せる。広大な屋敷構えを格式高く整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012698"},{"id":"00012696","register_sub_id":"101","register_pk":"367599","name":"永瀬孝男家住宅旧発電所","kana":"ながせたかおけじゅうたくきゅうはつでんしょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県川口市本町一丁目21-1","lat":35.79779278,"lng":139.72454194,"geo_status":"db","era":"明治33年頃／昭和14年頃改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木骨煉瓦造平屋建、金属板葺、建築面積63㎡","structure_material":"木骨煉瓦造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 182","desc":"もと自家発電施設で敷地東南隅に建つ。木骨煉瓦造平屋建、東西棟の切妻造鉄板葺で、東西二室に分けて北面に各出入口を設ける。躯体はフランス積で、東室の出入口をアーチ形とするなど丁寧につくる。類例の少ない住宅附属の発電施設の遺構として貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012696"},{"id":"00012694","register_sub_id":"101","register_pk":"367597","name":"永瀬孝男家住宅土蔵","kana":"ながせたかおけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県川口市本町一丁目21-1","lat":35.79779278,"lng":139.72454194,"geo_status":"db","era":"明治38年","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 180","desc":"洋館西側に接続して建つ家財蔵。土蔵造二階建、南北棟の切妻造桟瓦葺で東面中央に扉口を設ける。外壁は上部漆喰塗、下部モルタル洗出しで石造風につくる。内部は上下階とも板敷、小屋は和小屋とする。和館、洋館と並び建ち、格式高い屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012694"},{"id":"00012695","register_sub_id":"101","register_pk":"367598","name":"永瀬孝男家住宅納屋","kana":"ながせたかおけじゅうたくなや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県川口市本町一丁目21-1","lat":35.79779278,"lng":139.72454194,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、金属板葺、建築面積39㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 181","desc":"洋館北側に南面して建つ。木造二階建、切妻造鉄板葺で正面に一間幅の下屋を通す。内部は一面土間で西端に階段を設ける。二階は物置とし、正面に縦格子窓を穿つ。下屋は吹放し、西端を仕切って小部屋とする。鋳物業者の住宅の伝統的な構成を伝える附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012695"},{"id":"00012692","register_sub_id":"101","register_pk":"367595","name":"永瀬孝男家住宅洋館","kana":"ながせたかおけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"埼玉県","address":"埼玉県川口市本町一丁目21-1","lat":35.79779278,"lng":139.72454194,"geo_status":"db","era":"大正11年頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 178","desc":"市中心部にある鋳物業者の住宅。洋館は敷地中央に南面して建つ。木造二階建、急勾配の切妻造洋瓦葺で正面中央に玄関ポーチを付す。外観はドイツ壁と縦長窓を基調とし、玄関ポーチや内部の細部意匠をセセッション風とするなど大正期の洋風住宅の趣向を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012692"},{"id":"00012697","register_sub_id":"101","register_pk":"367600","name":"永瀬孝男家住宅煉瓦蔵","kana":"ながせたかおけじゅうたくれんがぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県川口市本町一丁目21-1","lat":35.79779278,"lng":139.72454194,"geo_status":"db","era":"明治44年頃","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木骨煉瓦造2階建、瓦葺、建築面積19㎡","structure_material":"木骨煉瓦造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 183","desc":"旧発電所西側に建つ道具蔵。木骨煉瓦造二階建、南北棟の切妻造桟瓦葺妻入で北面中央に戸口を設ける。イギリス積の躯体外面は漆喰塗で土蔵造風に仕上げる。内部は半間毎に柱を立て、上下階とも板敷とする。近代における鋳物業者の住宅の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012697"},{"id":"00012693","register_sub_id":"101","register_pk":"367596","name":"永瀬孝男家住宅和館","kana":"ながせたかおけじゅうたくわかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県川口市本町一丁目21-1","lat":35.79779278,"lng":139.72454194,"geo_status":"db","era":"明治38年頃／昭和前期改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 179","desc":"洋館東側に接続して建つ。寄棟造桟瓦葺の平屋建で東南北三面に下屋を廻す。内部は西に控間二室、東に10畳の座敷を設け、南東二面に縁を通す。座敷回りに良質な檜材を多用した丁寧なつくりの客座敷で、和洋館併設の格式高い屋敷構えの中核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012693"},{"id":"00012691","register_sub_id":"101","register_pk":"367594","name":"永瀬昌文家住宅主屋","kana":"ながせまさふみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川口市本町一丁目100","lat":35.79779278,"lng":139.72454194,"geo_status":"db","era":"昭和13年頃","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、瓦葺、建築面積202㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"11 － 177","desc":"市中心部にある鋳物業者の住宅。南正面の木造二階建、入母屋造桟瓦葺で正面東端に切妻造洋瓦葺の別棟が突出して接続する。内部は一階に居間等、二階に客間を配し、別棟に洋風の玄関と応接間を設ける。鋳物産業で発展した川口市街の歴史的景観を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012691"},{"id":"00003068","register_sub_id":"101","register_pk":"104058","name":"二木屋（旧小林英三家住宅）主屋","kana":"にきや（きゅうこばやしえいぞうけじゅうたく）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県さいたま市中央区大戸四丁目４１８","lat":35.867989,"lng":139.641464,"geo_status":"db","era":"昭和12頃／昭和23・25増築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積330㎡","structure_material":"木造平屋一部2階建","registered":"2003.01.31(平成15.01.31)","register_no":"11 － 0047","desc":"もと陸軍将校の別邸として建てられた住宅建築。１階を洋間とする北西方の２階建部分と，東側の雁行部分はそれぞれ昭和２３年，２５年の増築。大勢の客を迎え入れるために１８畳，１５畳の広間を持ち，現在では料亭として建物の公開を兼ねて活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003068"},{"id":"00003069","register_sub_id":"101","register_pk":"104059","name":"二木屋（旧小林英三家住宅）門及び塀","kana":"にきや（きゅうこばやしえいぞうけじゅうたく）もんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県さいたま市中央区大戸四丁目４１８-１","lat":35.86807121,"lng":139.64134498,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造、間口2.1m、塀延長58m","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"11 － 0048","desc":"敷地の東側と北側を画す塀。大谷石を６段に積む重厚な塀で，東面のほぼ中央には木製扉の門を開き，脇に通用口を設ける。主屋が建設された昭和１０年代初期は付近が住宅地として開けた時期に当たり，東京近郊の住宅地形成期の姿を今日に伝えている","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003069"},{"id":"00016363","register_sub_id":"101","register_pk":"536430","name":"繁田家住宅長屋門","kana":"はんだけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県入間市宮前町786-3他","lat":35.84498611,"lng":139.38311667,"geo_status":"db","era":"文政11年（1828）／昭和前期改修","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"11 - 0241","desc":"市街地の北東、角地に東面して建つ旧名主屋敷の長屋門。平屋建切妻造平入桟瓦葺で、外壁は漆喰壁で腰は簓子下見板張。門口の南側に配する続き間座敷は南西に縁を廻らし庭を望み、書院や欄間の組子など繊細なつくり。通りに面して歴史的景観に寄与する長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016363"},{"id":"00013950","register_sub_id":"101","register_pk":"508210","name":"久野家住宅店舗","kana":"ひさのけじゅうたくてんぽ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県草加市神明一丁目35","lat":35.83535,"lng":139.806475,"geo_status":"db","era":"江戸末期／平成23年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積54㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"11 - 0206","desc":"旧草加宿の北端で街道に東面する元商家。真壁造二階建、切妻造桟瓦葺。二階軒先を出桁造とし、一階に下屋を通し南半を戸口、北半に格子を建てる。内部は一、二階とも一室で活用する一方、正面に摺上戸の痕跡を残すなど、宿場町の面影を良く伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013950"},{"id":"00007456","register_sub_id":"101","register_pk":"108438","name":"逸見家住宅主屋","kana":"へんみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県秩父市荒川贄川字玉田812","lat":35.96463406,"lng":138.97802876,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積126㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"11 － 0124","desc":"秩父往還に舌状に面する敷地の中央に南面して建つ。桁行１３ｍ梁間７．８ｍの木造２階建で、切妻造桟瓦葺とする。１階は西に食違い四間取の床上部、東に土間を配し、背面に鉄板葺下屋の水まわりを張り出す。外壁は漆喰仕上げで、妻に束と貫からなる架構を現す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007456"},{"id":"00016361","register_sub_id":"101","register_pk":"536428","name":"星野家住宅主屋","kana":"ほしのけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"埼玉県","address":"埼玉県さいたま市緑区大字三室字東宿2119","lat":35.88606111,"lng":139.68135556,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積126㎡","structure_material":"木造平屋一部2階建","registered":"2025.11.17(令和7.11.17)","register_no":"11 - 0239","desc":"旧三室村の中心部に建つ旧家の主屋。設計は土屋巌。平屋建切妻造平入桟瓦葺の東西棟、東側は二階建で切妻造の妻をみせる。内部は西に広縁付座敷、東に一段低くサンルームを配し、要所に赤や青を用いアクセントとする。全体に均整が取れたモダンな意匠の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016361"},{"id":"00013228","register_sub_id":"101","register_pk":"366217","name":"星野家住宅主屋及び袖蔵","kana":"ほしのけじゅうたくおもやおよびそでぐら","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県入間郡越生町大字越生字町729","lat":35.96384722,"lng":139.29701111,"geo_status":"db","era":"明治41年／平成15年改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、瓦葺、建築面積127㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"11 － 0194","desc":"町東部の市街地に位置し、前面道路に北面して建つ。東の主屋は通りに面し、西の袖蔵は前庭を介し南にやや下がって建つ。主屋一階は前土間を持つ見世と奥に三室を配し、袖蔵は東側のミセに掛子塗の両開戸を開く。角地に建ち、旧道沿いの様相を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013228"},{"id":"00005254","register_sub_id":"101","register_pk":"106242","name":"細淵家住宅主屋","kana":"ほそぶちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県さいたま市南区沼影1-17-8","lat":35.84358045,"lng":139.64453973,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積129㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"11 － 0092","desc":"震災後に建てられた上質な民家建築。木造平屋建，寄棟造，桟瓦葺で，四周に銅板葺の下屋を廻し，南面して建つ。平面は六間取を基本とした伝統的形式であるが，土間を小さく造る。欅の良材を多用し，構造的に強固に造り，座敷などの内部意匠も洗練されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005254"},{"id":"00010265","register_sub_id":"101","register_pk":"199039","name":"三重家住宅主屋","kana":"みえけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川越市脇田町15-9","lat":35.909958,"lng":139.483897,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積156㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"11-0142","desc":"川越城下旧武家地の住宅街に建つ。主屋は本屋根と玄関を起りのある入母屋造として優雅な印象を与える。前後に三室ずつ並べて廊下を廻らし、主座敷は上質な座敷飾を備えて格天井を張り、品格を備える。居室と玄関を廊下で区分する近代住宅形式の好例となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010265"},{"id":"00010266","register_sub_id":"101","register_pk":"199040","name":"三重家住宅門","kana":"みえけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県川越市脇田町15-7","lat":35.90981036,"lng":139.48403951,"geo_status":"db","era":"昭和6年頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造、銅板葺、間口1.7m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"11-0143","desc":"敷地東辺南寄りに位置し、八幡通りに向けて開く。一間一戸の腕木門で左右に袖塀を附属する。わずかに起りをつけた切妻屋根を軽やかにかける。袖塀は竪板壁の上部を挽き板の目透し欄間とし、銅板葺の屋根をかける。主屋前の庭園とともに閑静な佇まいを醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010266"},{"id":"00003825","register_sub_id":"101","register_pk":"104815","name":"宮前家住宅表門","kana":"みやまえけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町993","lat":35.99598659,"lng":139.08405637,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造、瓦葺、間口2.0m","structure_material":"木造","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0062","desc":"西側が通りに面した敷地西辺のほぼ中央に在る。間口２ｍの小規模な１間１戸棟門で，軒は木舞打の一軒疎垂木，切妻造，桟瓦葺の屋根を架ける。主屋の和風意匠とよく通じており，内法差物や親柱の隅面を名栗仕上げとするなど，要所に繊細な造形がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003825"},{"id":"00003824","register_sub_id":"101","register_pk":"104814","name":"宮前家住宅主屋","kana":"みやまえけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"埼玉県","address":"埼玉県秩父市番場町993","lat":35.996002,"lng":139.084213,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"11 － 0061","desc":"建築家・山田醇の設計になる木造２階建住宅。中央部が東西棟の切妻造の２階建，西と東の１階部分が南北棟の切妻造で，破風を多用した変化のある外観を構成する。外観は建具等を含め洋風を基調とするが，内部は和風となり，和洋が巧みに纏められている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003824"},{"id":"00011861","register_sub_id":"101","register_pk":"211049","name":"安達家住宅座敷","kana":"あだちけじゅうたくざしき","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁字新宿町424-1","lat":36.279316,"lng":140.101931,"geo_status":"db","era":"江戸末期／昭和45年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"08 - 0301","desc":"主屋の西側に接続する。寄棟造、桟瓦葺で、式台玄関を開き、九畳、一〇畳、八畳の三室を並べる。八畳には床・床脇・付書院を、一〇畳には二間半の大床を設け、接客のための座敷として格式ある構えを見せる。商家の暮らしぶりを今に伝える遺構の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011861"},{"id":"00011860","register_sub_id":"101","register_pk":"211048","name":"安達家住宅見世蔵及び主屋","kana":"あだちけじゅうたくみせぐらおよびしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁字新宿町424-1","lat":36.279215,"lng":140.101977,"geo_status":"db","era":"江戸末期／平成7年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積135㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"08 - 0300","desc":"新宿通り北側に建つ。桁行五間平入の見世蔵に主屋が直交する。いずれも二階建で土蔵造とするのが特徴。東を土間とし、西に帳場や居間等を配する。階高が低く、出桁造で軒蛇腹まで塗込め、観音扉の窓など重厚な外観に、江戸末期の当地域の町家の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011860"},{"id":"00011862","register_sub_id":"101","register_pk":"211050","name":"安達家住宅薬医門","kana":"あだちけじゅうたくやくいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁字新宿町424-1","lat":36.279236,"lng":140.101894,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.6m、左右袖塀及び東方潜戸付","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"08 - 0302","desc":"座敷の正門として、新宿通りに開く。間口二・六メートルの一間一戸薬医門で、東西に袖塀を設け、東方に潜戸を開く。一軒疎垂木であり、屋根は正面を本瓦葺、背面を桟瓦葺とし、当地域では例をみない本瓦葺の外観で、街路景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011862"},{"id":"00001237","register_sub_id":"101","register_pk":"102227","name":"荒川家住宅内蔵","kana":"あらかわけじゅうたくうちぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県筑西市甲868","lat":36.31132685,"lng":139.98079201,"geo_status":"db","era":"明治初","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積50㎡","structure_material":"土蔵造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0010","desc":"奥座敷としての付属屋の背後に位置する南北棟、桟瓦葺切妻屋根、２階建の土蔵。桁行四間、梁間三間の妻入の蔵で、南面に黒漆喰塗の観音扉を付け、奥座敷の廊下を蔵前とする。奥座敷側の壁面は松と鶴の鏝絵仕上げとするなど丁寧な造りの蔵になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001237"},{"id":"00001234","register_sub_id":"101","register_pk":"102224","name":"荒川家住宅主屋","kana":"あらかわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県筑西市甲868","lat":36.31118716,"lng":139.98076049,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造３階建，瓦葺，建築面積139㎡","structure_material":"木造３階建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0007","desc":"下館の中心街である田町の国道沿いに南面して建つ荒七酒店の住宅部。木造３階建、モルタル塗のアール・デコ調の洋館であるが、３階の屋根は宝形屋根とし帝冠様式的雰囲気をも感じさせる特異な外観意匠をもつ。通りのランドマークにもなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001234"},{"id":"00001236","register_sub_id":"101","register_pk":"102226","name":"荒川家住宅付属屋","kana":"あらかわけじゅうたくふぞくや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県筑西市甲868","lat":36.31129583,"lng":139.98077766,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建，瓦葺，建築面積50㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"08 － 0009","desc":"３階建洋館の北方背後につながる平屋建、桟瓦葺、寄棟屋根の建物で、店蔵の改築に引き続いて既存の内蔵とをつなぐかたちで建てられた奥座敷。中庭にむけて鉄板葺の庇を差出して座敷回りに廊下をめぐらす。屋敷構えの形成過程を物語る建物とすることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001236"},{"id":"00001999","register_sub_id":"101","register_pk":"102989","name":"伊勢屋旅館土蔵","kana":"いせやりょかんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字下宿町193","lat":36.27712373,"lng":140.09955917,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"08 － 0049","desc":"土蔵は主屋の北側，敷地のほぼ中央に建つ。桁行２間半，梁間１間半と規模は小さいが，南北棟の切妻造・桟瓦葺で，東面に下屋庇を設ける。２階南面の観音扉は丁寧なつくりで，外壁は白漆喰塗であるが，西側の腰を横板張，南側１階を海鼠壁として変化に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001999"},{"id":"00003376","register_sub_id":"101","register_pk":"104366","name":"市塚章一家住宅長屋門","kana":"いちつかしょういちけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町飯塚74","lat":36.27685986,"lng":140.09639945,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0098","desc":"間口１６．５ｍ規模の木造平屋建，寄棟造，桟瓦葺で，軒は出桁造で疎垂木を配る。中央部は欅材を用いた丁寧なつくりの門口で，正面左右は漆喰塗に腰海鼠壁，ほかは真壁造とする。真壁で唯一の海鼠壁をもつ長屋門で，敷地北側の街路景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003376"},{"id":"00003506","register_sub_id":"101","register_pk":"104496","name":"市塚政一家住宅長屋門","kana":"いちつかまさいちけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町飯塚26","lat":36.276878,"lng":140.096939,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0111","desc":"街路に南面して建つ。桁行９間，梁間２間半の規模で，寄棟造，桟瓦葺の木造平屋建とし，軒を出桁造とする。正面右側を穀物蔵，左側を納屋とし，外装は腰を簓子下見板張，上部を漆喰塗壁，門の本柱の両脇には潜戸を設ける。真壁において比較的大規模な長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003506"},{"id":"00003377","register_sub_id":"101","register_pk":"104367","name":"市塚昌宏家住宅表門","kana":"いちつかまさひろけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町飯塚85","lat":36.27662304,"lng":140.09779228,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口2.5m、左右袖塀付","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0099","desc":"間口２．７ｍの１間１戸薬医門で，左右に真壁造の袖壁を付ける。屋根はすべて切妻造，桟瓦葺，１軒疎垂木である。扉は金具吊でなく，上下とも藁座に取り付ける。通称飯塚通りと称する街路に面した敷地北辺に建ち，屋敷の表構えと街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003377"},{"id":"00002204","register_sub_id":"101","register_pk":"103194","name":"一色家住宅主屋","kana":"いっしきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県土浦市西真鍋町1918-1","lat":36.09547,"lng":140.19751,"geo_status":"db","era":"文久3","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造平屋建、茅葺、建築面積201㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0052","desc":"新郭と呼ばれる土浦藩の新武家屋敷地に遺る唯一の武家屋敷遺構。主体部は桁行８間半，梁行４間規模で，茅葺寄棟造に造り，内部は８畳間４室を田の字型に配し，南面と北面に縁廊下を回す。藩家老で，近代には地元銀行を創設した一色家の居宅として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002204"},{"id":"00001871","register_sub_id":"101","register_pk":"102861","name":"猪瀬家住宅薬医門","kana":"いのせけじゅうたくやくいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁1","lat":36.27637966,"lng":140.1014219,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造薬医門、瓦葺、間口3.0m","structure_material":"木造薬医門","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0044","desc":"間口３メートルの１間１戸薬医門で，内開きの板扉を吊り，両側の袖塀に小さな潜戸を設ける。親柱には小平を用い，成の高い桁を乗せ，絵様虹梁を連三斗組で受け，棟木は笈形付太瓶束で支える。欅材を用いた丁寧なつくりで，装飾細部は明治初期の造形をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001871"},{"id":"00003357","register_sub_id":"101","register_pk":"104347","name":"茨城大学五浦美術文化研究所岡倉天心旧居（研究室）","kana":"いばらぎだいがくいづらびじゅつぶんかけんきゅうじょおかくらてんしんきゅうきょ（けんきゅうしつ）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県北茨城市大津町五浦727-2","lat":36.83357924,"lng":140.80281886,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0079","desc":"太平洋を望む絶好地にある。ほぼ東向きの木造平屋建で，緩勾配の屋根はもと木羽葺。中心部は客間や居間からなり，北に玄関，北西に勝手を配し，当初は南西に奥の間があった。設計は岡倉天心自身で，棟梁は地元の小倉源蔵。古材を用いた瀟洒な数寄屋風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003357"},{"id":"00003358","register_sub_id":"101","register_pk":"104348","name":"茨城大学五浦美術文化研究所長屋門（管理舎・陳列館）","kana":"いばらぎだいがくいづらびじゅつぶんかけんきゅうじょながやもん（かんりしゃ・ちんれつかん）","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県北茨城市大津町五浦727-2","lat":36.83369234,"lng":140.80246952,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、杉皮葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0080","desc":"屋敷地の西方，西面して建つ桁行１６．４ｍの細長い建物で，屋根は入母屋造，杉皮葺である。平面は北側を折り曲げたＬ字型で，中央北寄を門口とする。旧居同様に古材を使い，外壁には簓子下見板張を多用するなど，伝統的な形式を数寄屋風意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003358"},{"id":"00008091","register_sub_id":"101","register_pk":"132489","name":"岩瀬家住宅表門","kana":"いわせけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県土浦市小山崎字道知411-1他","lat":36.13332892,"lng":140.19048768,"geo_status":"db","era":"江戸末期／昭和58年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、銅板葺、間口2.9m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"08 － 0236","desc":"敷地の南端、道路に面して建つ。間口２．９ｍに本柱を建て、冠木で固める。本柱と控柱は柱間２．７ｍと広くとり、貫や梁で繋ぎ、束を建て棟木を支持する。一軒疎垂木。本柱間には両開の板扉を吊る。当初は茅葺で、簀の子野地を残す。名主屋敷の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008091"},{"id":"00008089","register_sub_id":"101","register_pk":"132487","name":"岩瀬家住宅米蔵","kana":"いわせけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県土浦市小山崎字道知411-1他","lat":36.13401654,"lng":140.19040672,"geo_status":"db","era":"江戸末期／明治後期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"08 － 0234","desc":"主屋背面に軸線を扇形に振って建ち並ぶ建物群の西端に位置する。切妻造桟瓦葺の置屋根、正面３．６ｍ奥行６．３ｍの土蔵造２階建。南妻を正面とし、庇を付け、東面に真壁造の袖倉を付ける。切石積基礎上、白漆喰塗仕上げ。主屋背後の景観に重みを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008089"},{"id":"00007448","register_sub_id":"101","register_pk":"108430","name":"岩瀬家住宅主屋","kana":"いわせけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県土浦市小山崎字道知411-1他","lat":36.13372786,"lng":140.19052514,"geo_status":"db","era":"安政5頃／明治中期・昭和中期改修","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積366㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"08 － 0228","desc":"敷地のほぼ中央に南面して建つ。桁行２６ｍ梁間１１ｍ規模の木造平屋建で、寄棟造茅葺（銅板仮葺）とする。内部は東寄りを土間とし、西側を前後２列の居室とする。西端に続き座敷を設け、北側の主座敷に座敷飾りを構える。規模が大きく、風格のある農家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007448"},{"id":"00008092","register_sub_id":"101","register_pk":"132490","name":"岩瀬家住宅中ノ門","kana":"いわせけじゅうたくなかのもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県土浦市小山崎字道知411-1他","lat":36.13373312,"lng":140.19080859,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.5m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"08 － 0237","desc":"主屋の東に延びる塀の先に東西棟で建ち、敷地の南・北を仕切る。間口２．５ｍの一間高麗門。切妻造桟瓦葺で、控えは銅板葺。本柱を楣貫で繋ぎ、前後に腕木を出し、軒桁を支持。中備に束を建て、貫を通して固め、腕木を出す。一軒疎垂木。成の高い簡素な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008092"},{"id":"00008093","register_sub_id":"101","register_pk":"132491","name":"岩瀬家住宅東門","kana":"いわせけじゅうたくひがしもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県土浦市小山崎字道知411-1他","lat":36.13349623,"lng":140.19078744,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.6m、袖塀付","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"08 － 0238","desc":"敷地東辺に南北棟で建つ通用門で、両袖に真壁造桟瓦葺の塀が付く。間口２．６ｍに本柱、その背後心々１．８ｍに控柱を建てる。柱上部に冠木等を載せ、本・控柱間に梁を架けて固める。一軒疎垂木で、切妻造桟瓦葺。表門と比べて簡素ながら、同じ特殊な架構になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008093"},{"id":"00008094","register_sub_id":"101","register_pk":"132492","name":"岩瀬家住宅塀","kana":"いわせけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県土浦市小山崎字道知411-1他","lat":36.13327632,"lng":140.19060195,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、銅板葺、延長46m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"08 － 0239","desc":"敷地東辺に南北棟で建つ通用門で、両袖に真壁造桟瓦葺の塀が付く。間口２．６ｍに本柱、その背後心々１．８ｍに控柱を建てる。柱上部に冠木等を載せ、本・控柱間に梁を架けて固める。一軒疎垂木で、切妻造桟瓦葺。表門と比べて簡素ながら、同じ特殊な架構になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008094"},{"id":"00008090","register_sub_id":"101","register_pk":"132488","name":"岩瀬家住宅味噌倉","kana":"いわせけじゅうたくみそぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県土浦市小山崎字道知411-1他","lat":36.13397847,"lng":140.19068591,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積40㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"08 － 0235","desc":"米蔵の東に位置する。切妻造桟瓦葺、桁行５．６ｍ梁間５．０ｍの木造２階建で、１階内部は味噌置場と物置の二室に分ける。西面から南面にかけて下屋庇をまわす。下屋は土間で西面を吹き放つ。外壁は真壁造で、白漆喰仕上げ。深い下屋庇が外観に安定感を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008090"},{"id":"00008088","register_sub_id":"101","register_pk":"132486","name":"岩瀬家住宅屋敷蔵","kana":"いわせけじゅうたくやしきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県土浦市小山崎字道知411-1他","lat":36.13364006,"lng":140.19027136,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"08 － 0233","desc":"南面する主屋の西南に南北棟で建つ。切妻造桟瓦葺の置屋根で、東面全面に庇を付ける。桁行６．４ｍ梁間４．２ｍの土蔵造２階建。外壁は黒漆喰仕上げとする。内部は白漆喰仕上げで、貫を現す。壁に接して、物入を作る。大規模な主屋に相応する構えになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008088"},{"id":"00001404","register_sub_id":"101","register_pk":"102394","name":"潮田家住宅別荘（離れ）","kana":"うしおだけじゅうたくべっそう（はなれ）","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁189","lat":36.27713876,"lng":140.09881838,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積98㎡","structure_material":"木造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"08 － 0020","desc":"敷地の西側に建ち，見世蔵と渡り廊下で結ばれている。総２階建，寄棟造・桟瓦葺であるが，周囲に縁を廻して開放的な平面とする。全体に良質の材を用い，床・棚・付書院など丁寧な数寄屋風にまとめられ，地方の近代接客空間の意匠を端的にあらわしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001404"},{"id":"00001403","register_sub_id":"101","register_pk":"102393","name":"潮田家住宅脇蔵","kana":"うしおだけじゅうたくわきぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁189","lat":36.27731155,"lng":140.09905135,"geo_status":"db","era":"明治30以前","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積58㎡","structure_material":"土蔵造2階建","registered":"1999.11.18(平成11.11.18)","register_no":"08 － 0019","desc":"潮田家は屋号を「鶴屋」と称し，広い屋敷地をもっている。脇蔵は見世蔵・袖蔵の北側に空地を挟み，通りよりやや離れて建つ。総２階建・切妻造・桟瓦葺であるが，袖蔵よりひとまわり大きく，建築年代も古い。大規模商家の屋敷構成に欠かせない存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001403"},{"id":"00005236","register_sub_id":"101","register_pk":"106224","name":"大貫家住宅主屋","kana":"おおぬきけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県東茨城郡大洗町磯浜町字道祖神脇1130-3","lat":36.31404454,"lng":140.56825114,"geo_status":"db","era":"大正元／大正15移築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積142㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"08 － 0203","desc":"町中心部の西側に位置し，かつて醸造業を営んでいた商家の主屋。桁行１２．７ｍ，梁間１１．９ｍ規模の木造２階建，桟瓦葺で，内部は良材を用いた丁寧な造りとする。西面及び南面は出桁で深い軒をつくり，西面を入母屋屋根とした堂々とした外観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005236"},{"id":"00005104","register_sub_id":"101","register_pk":"106094","name":"大場家住宅主屋","kana":"おおばけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県石岡市佐久258-2","lat":36.26244743,"lng":140.2018705,"geo_status":"db","era":"江戸末期頃","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期頃","structure":"木造平屋建、茅葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"08 － 0201","desc":"敷地中央に南面して建ち，桁行８間，梁間４間半の規模とし，寄棟造，茅葺，平入，木造平屋建とする。間取りや床の間等の形式，差鴨居の使い方に古式を留め，軒二方にせがいを付け，茅屋根は軒先や棟飾りに特徴があり，規模が大きく見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005104"},{"id":"00003949","register_sub_id":"101","register_pk":"104939","name":"大森家住宅石蔵","kana":"おおもりけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町桜井字東169-1","lat":36.28049886,"lng":140.10391642,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"石造一部土蔵造2階建、瓦葺、建築面積76㎡","structure_material":"石造一部土蔵造2階建","registered":"2004.03.02(平成16.03.02)","register_no":"08 － 0122","desc":"長屋門の南に続き表通りに沿って建つ。桁行４間梁間３間，切妻造の妻入，桟瓦葺で，１階を石造，２階は木造とする。外部は１階に花崗岩の石壁を表し，２階は漆喰大壁で，軒に鉢巻を回す。特徴ある構造と外観をもつ上質な蔵で，屋敷の表構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003949"},{"id":"00003948","register_sub_id":"101","register_pk":"104938","name":"大森家住宅長屋門","kana":"おおもりけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町桜井字東169-1","lat":36.28056133,"lng":140.10396973,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"08 － 0121","desc":"主屋の南に接して門口を開き，その南に小部屋を配し，切妻造，桟瓦葺の屋根を架ける。正面側は，門口の軒を二重の出桁造とし，南小部屋外部は漆喰で塗り込め下半は高く下見板張とする。小規模だが特徴ある形式で，屋敷の表構えを構成する主要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003948"},{"id":"00004503","register_sub_id":"101","register_pk":"105493","name":"奥順土蔵","kana":"おくじゅんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町9-2、字西の宮町1336-2","lat":36.30380528,"lng":139.87752474,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0163","desc":"見世蔵の北背後に位置する土蔵造２階建。桁行５間梁間２間半の東西棟で，屋根は切妻造，桟瓦葺。外壁は白漆喰塗で，腰を袴状に塗り出し，北面２階は押縁下見板張とする。南面東寄りに両開の漆喰塗戸を釣り込んだ戸口を設け，南面と北面に下屋を付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004503"},{"id":"00004502","register_sub_id":"101","register_pk":"105492","name":"奥順離れ","kana":"おくじゅんはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町9-2、12-2","lat":36.30371598,"lng":139.87736256,"geo_status":"db","era":"明治19","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0162","desc":"店舗の北背後に並ぶ，桁行３間半梁間３間の木造平屋建で，屋根を寄棟造の桟瓦葺とし，四周に瓦葺庇を巡らす。内部は北に床・棚・書院付きの８畳座敷，南に６畳と３畳を配し，庇部にガラス障子を建て込んだ縁が巡る。屋敷構えの主要な構成要素のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004502"},{"id":"00007452","register_sub_id":"101","register_pk":"108434","name":"小澤家住宅表門","kana":"おざわけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県稲敷郡美浦村大字大谷字向1620","lat":36.00053642,"lng":140.32309945,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"08 － 0232","desc":"通りから少し入った位置、主屋の南に近接して建つ。間口２．７ｍと規模の大きい薬医門で、両脇に袖塀を付ける。切妻造桟瓦葺。主柱と控柱のそれぞれに冠木を置き、２段に梁を架け渡す。部材はいずれも角材。軒は一軒半繁垂木。直線的で力強い意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007452"},{"id":"00007451","register_sub_id":"101","register_pk":"108433","name":"小澤家住宅米蔵","kana":"おざわけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県稲敷郡美浦村大字大谷字向1620","lat":36.00051186,"lng":140.32327842,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"08 － 0231","desc":"主屋の東方に位置する。桁行６．８ｍ梁間３．９ｍの土蔵造２階建。切妻造妻入鉄板葺で、西面に掛子塗の両開戸を吊り、桟瓦葺庇を掛ける。腰板張の白漆喰仕上げで、東面上部に庇付の窓を開ける。１階は土間で板壁、２階は真壁で、登梁組。正面妻に屋号を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007451"},{"id":"00007450","register_sub_id":"101","register_pk":"108432","name":"小澤家住宅主屋","kana":"おざわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県稲敷郡美浦村大字大谷字向1620","lat":36.00064504,"lng":140.32311286,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、茅葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"08 － 0230","desc":"敷地後方に南北棟で建つ。大規模な寄棟造茅葺民家で、東面北端に入母屋造式台を付ける。式台は間口２間、出桁造で扇垂木とする。その奥に次の間と座敷が続き、座敷にはトコと違棚、付書院を備える。風格ある構えのなか、繊細な欄間や銀箔貼襖など意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007450"},{"id":"00002876","register_sub_id":"101","register_pk":"103866","name":"川島洋品店土蔵","kana":"かわしまようひんてんどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁302","lat":36.27876192,"lng":140.09955148,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積37㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"08 － 0070","desc":"町中心部，御陣屋前通り北端西側の川島洋品店敷地内の北西端にある。桁行４間，梁間２間の規模を有す，切妻造，平入，桟瓦葺の総２階建で，漆喰塗を基調としつつ，妻面全体を簓子下見板張とした外装と，垂木にあわせて波状に塗籠めた軒裏を特徴とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002876"},{"id":"00016357","register_sub_id":"101","register_pk":"536424","name":"川田家住宅石塀及び板塀","kana":"かわだけじゅうたくいしべいおよびいたべい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県つくば市北条字古城97","lat":36.1776,"lng":140.09413611,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"石塀 石造、延長15m 板塀 石造及び木造、延長26m","structure_material":"石塀 石造","registered":"2025.11.17(令和7.11.17)","register_no":"08 - 0325","desc":"敷地東面を画す石塀及び板塀。石塀は切石積で、道路の前面部分を御影石積とし、それ以外を大谷石積とする。石塀に続く板塀は大和塀で、御影石の独立柱を立てて、柱間に御影石の地覆を据え、木製貫を通して竪板を張る。通りに面して歴史的な景観を形成する塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016357"},{"id":"00016355","register_sub_id":"101","register_pk":"536422","name":"川田家住宅主屋","kana":"かわだけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市北条字古城97","lat":36.17772222,"lng":140.09413333,"geo_status":"db","era":"明治後期／大正後期移築、昭和前期・平成13年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積139㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"08 - 0323","desc":"北条の町並みの中心部に位置する住宅主屋。敷地中央に南面する平屋建寄棟造妻入桟瓦葺で軒を出桁造とする。内部の南に土間、北に四間取を配す。スギの四方柾の柱やケヤキの一枚板の縁板など用材を吟味し、付書院の組子など繊細なつくりとした近代和風の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016355"},{"id":"00016356","register_sub_id":"101","register_pk":"536423","name":"川田家住宅炊事場及び風呂","kana":"かわだけじゅうたくすいじばおよびふろ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県つくば市北条字古城97","lat":36.17788889,"lng":140.09426111,"geo_status":"db","era":"大正後期／令和3年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"08 - 0324","desc":"主屋の北東にある炊事場及び風呂場。平屋建、急勾配の切妻造妻入スペイン瓦葺。外壁は縦長窓を並べ、モルタル塗で上部は黄土色とし、腰は洗出仕上で覆輪目地を切って石貼風とする。内部は土間で南に炊事場、北に風呂場を配す。洋風の外観を持つ珍しい附属屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016356"},{"id":"00001866","register_sub_id":"101","register_pk":"102856","name":"木村家住宅（小田部生花店）主屋","kana":"きむらけじゅうたく（こたべせいかてん）しゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁字高上町217-1","lat":36.27770995,"lng":140.09920142,"geo_status":"db","era":"嘉永6以前","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積79㎡","structure_material":"土蔵造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0039","desc":"主屋は見世蔵と棟を直交させ，背面北寄りに接続して建つ切妻造・２階建の土蔵造建築。桁行６間・梁間３間半の規模を持ち，１階は和室３室と板の間など，２階は床や棚を備えた和室３室からなる。見世蔵と主屋が土蔵造で一体的に建設されたところが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001866"},{"id":"00002878","register_sub_id":"101","register_pk":"103868","name":"木村家住宅門","kana":"きむらけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁字高上町217-1","lat":36.277737,"lng":140.09934287,"geo_status":"db","era":"嘉永6頃","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2002.08.21(平成14.08.21)","register_no":"08 － 0072","desc":"町中心部，御陣屋前通り西側に面する。街路から少し奥まった位置に建つ，桟瓦葺，１間１戸の薬医門。町内の門で建設年代のはっきりしているものでは最古の遺構になる。屋根に緩やかな反りをもたせて，真壁の街路景観に風格と彩りを与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002878"},{"id":"00016644","register_sub_id":"101","register_pk":"579128","name":"旧飯島家住宅主屋","kana":"きゅういいじまけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県牛久市牛久町字上町90","lat":35.965364,"lng":140.136344,"geo_status":"db","era":"明治4年／明治17年頃・昭和中期増築","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積210㎡","structure_material":"木造平屋一部2階建","registered":"2026.07.09(令和8.07.09)","register_no":"08 - 0333","desc":"牛久宿北側に位置する旧家の主屋。寄棟造桟瓦葺で正面北側に式台を配し、南寄りは２階建とする。北側は四室を並べ、玄関を挟み南側に台所を配し、北西座敷は大床を構え、透彫欄間の付書院など上質なつくり。明治天皇行在所となった主屋で宿場の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016644"},{"id":"00016645","register_sub_id":"101","register_pk":"579129","name":"旧飯島家住宅蔵","kana":"きゅういいじまけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県牛久市牛久町字上町90","lat":35.965329,"lng":140.13598,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、瓦葺、建築面積37㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"08 - 0334","desc":"主屋の西方に位置する旧文庫蔵。石積基礎に建つ木造２階建切妻造桟瓦葺で東面に戸口を設けて下屋を付す。外壁は押縁下見板張。各階一室の板敷で、中央に階段を配し、北面に押入を設ける。小屋組はキングポスト・トラス。全体質実なつくりで敷地景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016645"},{"id":"00016646","register_sub_id":"101","register_pk":"579130","name":"旧飯島家住宅門及び塀","kana":"きゅういいじまけじゅうたくもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県牛久市牛久町字上町90","lat":35.965433,"lng":140.136645,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"門 木造、瓦葺、間口2.6m 塀 木造及びコンクリート造、鉄板葺、総延長39m","structure_material":"門 木造","registered":"2026.07.09(令和8.07.09)","register_no":"08 - 0335","desc":"水戸街道に東面して建つ門及び塀。門は一間薬医門、切妻造桟瓦葺で４筋の梁を架け、軒桁を受ける、軒は一軒繁垂木。門の南北に延びる塀は屋根鉄板葺とし、壁は竪板張の目透し部に竹を入れた丁寧なつくり。街道に面し、家格に相応しい表構えをつくる門及び塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016646"},{"id":"00010096","register_sub_id":"101","register_pk":"197929","name":"旧稲田家住宅赤煉瓦蔵","kana":"きゅういなだけじゅうたくあかれんがぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県常陸太田市東一町字東一東2295-2","lat":36.540978,"lng":140.523702,"geo_status":"db","era":"明治43／平成23改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造3階建、鋼板葺、建築面積23㎡","structure_material":"煉瓦造3階建","registered":"2014.10.07(平成26.10.07)","register_no":"08 － 0259","desc":"地主であった稲田家の袖蔵として建てられた。桁行三間梁間二間、妻入の煉瓦造三階建で、ペディメントを飾り、コーニスを廻らす。二、三階の両妻面に黒漆喰で掛子塗とした観音開きの扉を設け、高い左官技術を見せる。鯨ヶ丘の街路景観に寄与する重厚な煉瓦蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010096"},{"id":"00006437","register_sub_id":"101","register_pk":"107420","name":"旧植竹庄兵衛家住宅土蔵","kana":"きゅううえたけしょうべえけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県稲敷市江戸崎字大日久保甲2354","lat":35.96530564,"lng":140.32539344,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"08 － 0225","desc":"和館の西北隅に接して建つ、東西棟の土蔵造２階建。桁行３間、梁間２間、平入の切妻造桟瓦葺とし、外壁を目地切りモルタル塗仕上げとする。南面東端に出入口を開き、両妻に庇及び袖壁を付けた窓を穿つ。小屋組を二重梁組とし、力強い意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006437"},{"id":"00006237","register_sub_id":"101","register_pk":"107221","name":"旧植竹庄兵衛家住宅洋館","kana":"きゅううえたけしょうべえけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県稲敷市江戸崎字大日久保甲2354","lat":35.965237,"lng":140.325668,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、スレート葺、建築面積173㎡、煙突付","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"08 － 0223","desc":"江戸崎入干拓地を東に望む高台に建つ。桁行１１ｍ、梁間９．２ｍの木造２階建洋館で南面する。スレート葺、半切妻屋根に半円のペディメントを付ける。モルタル塗の外壁は石造に見せるため目地を切る。アール・デコほかの影響が所々に見られ、見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006237"},{"id":"00006436","register_sub_id":"101","register_pk":"107419","name":"旧植竹庄兵衛家住宅和館","kana":"きゅううえたけしょうべえけじゅうたくわかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県稲敷市江戸崎字大日久保甲2354","lat":35.96522411,"lng":140.3255029,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"08 － 0224","desc":"洋館の西側に建つ和館で、庭に南面して建つ。桁行６間、梁間５間で、緩い起りの入母屋造銅板葺屋根とする木造平屋建。１０畳２室と６畳間からなり、正・側三方に縁廊下が廻る。座敷飾りや折上格天井、欄間のステンドグラスなど内部は凝った意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006436"},{"id":"00003777","register_sub_id":"101","register_pk":"104767","name":"旧小野瀬家住宅主屋","kana":"きゅうおのせけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県龍ケ崎市4252","lat":35.90591801,"lng":140.18799307,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"08 － 0113","desc":"店舗背面玄関部の北に建つ。南北棟，片寄棟造，桟瓦葺の木造平屋建で，６畳・６畳・８畳の３室を南北に並べ，８畳西面に床と棚を構える。東面と北面に縁廊下を廻し，北西端に便所を配する。大正初期建築の剛直な店舗に比して低平で端整なつくりに特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003777"},{"id":"00011253","register_sub_id":"101","register_pk":"209088","name":"旧尾見家住宅主屋","kana":"きゅうおみけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県筑西市村田字下町1624","lat":36.272638,"lng":140.01096,"geo_status":"db","era":"嘉永元年","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積401㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"08－0294","desc":"木造平屋建、寄棟造桟瓦葺、桁行三一メートル、梁間二三メートルの大規模農家。床上部は三列七室の南・西に一間幅の入側を廻らす。背面西端には六畳二間や風呂・便所を突出する。正面床上部中央列に式台玄関を備えるなど、名主にふさわしい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011253"},{"id":"00011254","register_sub_id":"101","register_pk":"209089","name":"旧尾見家住宅神輿蔵","kana":"きゅうおみけじゅうたくみこしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県筑西市村田字下町1624","lat":36.272493,"lng":140.010637,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積9.9㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"08－0295","desc":"主屋の南西寄りに建つ。三メートル四方の入母屋造桟瓦葺で、正面には向拝を設ける。基礎は洗出しとし、長押下を正面は鱗文様の銅板、側背面は下部を石積風に見せる鉄板で覆う。内部は一室で土間とし、尾見家が所有していた神輿を収めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011254"},{"id":"00011255","register_sub_id":"101","register_pk":"209090","name":"旧尾見家住宅薬医門","kana":"きゅうおみけじゅうたくやくいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県筑西市村田字下町1624","lat":36.272274,"lng":140.011025,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、茅葺、間口2.5m","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"08－0296","desc":"主屋の南に建つ。間口二・五メートルの一間一戸薬医門で、小屋は叉首組とし、屋根は茅葺である。門扉の板戸を含め、全体に金具等を用いない簡素な造りとするが、茅葺を残す希少な門であり、往時の屋敷構えを知るうえで欠かすことができない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011255"},{"id":"00015278","register_sub_id":"101","register_pk":"532402","name":"旧紫山塾主屋","kana":"きゅうしざんじゅくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県土浦市真鍋五丁目2132","lat":36.09924444,"lng":140.20104444,"geo_status":"db","era":"昭和3年／昭和51年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、銅板葺、建築面積92㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"08 - 0320","desc":"八坂神社の東隣に位置する水戸学の旧私塾兼住宅主屋。敷地中央に建つ２階建寄棟造で屋根瓦棒銅板葺。東面に入母屋造の玄関を突出し、全体矩折の平面とする。二階は床と違棚を備えた続き間座敷で、床柱は出節丸太とするなど趣向を凝らした近代和風の住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015278"},{"id":"00010744","register_sub_id":"101","register_pk":"201579","name":"旧根本家住宅主屋","kana":"きゅうねもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県つくば市吉瀬字清水1680","lat":36.084352,"lng":140.149384,"geo_status":"db","era":"江戸末期／明治19頃移築・大正期・昭和56・平成24改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積191㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0279","desc":"集落内の敷地中央に東面して建つ。正面は、右手の土間に戸口を開き、中央に縁を設け、上手に式台を構える。軒はせがい造で下屋を廻らせる。床上部は四間取系平面をもち、前列上手の座敷に床と物入れを備える。つくば市郊外における近世上層農家の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010744"},{"id":"00010745","register_sub_id":"101","register_pk":"201580","name":"旧根本家住宅長屋門","kana":"きゅうねもとけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市吉瀬字清水1680","lat":36.084394,"lng":140.149718,"geo_status":"db","era":"明治19／昭和58改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0280","desc":"主屋正面に構え、木造平屋建、寄棟造桟瓦葺である。軒をせがい造とし、中央の門口ではさらに冠木上に男梁と肘木を組み、ケヤキ板戸を吊り、重厚に見せる。南北の室は腰を簓子下見板張とし、かつては蔵や作業部屋などに使用した。屋敷構えに風格を添える長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010745"},{"id":"00012280","register_sub_id":"101","register_pk":"531604","name":"旧諸岡家住宅煉瓦門及び塀","kana":"きゅうもろおかけじゅうたくれんがもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県龍ケ崎市上町4274-1","lat":35.90548611,"lng":140.18540556,"geo_status":"db","era":"明治後期／平成27年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"門 煉瓦造 間口3.7m、左右脇柱付 塀 煉瓦造、総延長10m","structure_material":"門 煉瓦造 間口3.7m","registered":"2018.05.10(平成30.05.10)","register_no":"08-303","desc":"実業家諸岡良佐の邸宅から移設した煉瓦造の門及び塀で、高さ3・8メートルの門柱一対とやや低い脇門の門柱一対、両側の高さ2・2メートルの塀からなる。門柱上部に帯状の凸部を廻らし、柱天に柱頭飾風の張出しを付ける。重厚な表構えを伝える門塀である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012280"},{"id":"00014452","register_sub_id":"101","register_pk":"512436","name":"旧渡辺甚吉邸主屋","kana":"きゅうわたなべじんきちていおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県取手市寺田字原5270-8他","lat":35.91065556,"lng":140.05633889,"geo_status":"db","era":"昭和9年／令和4年移築","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積225㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"08 - 0318","desc":"もと東京白金台に所在した邸宅。外観は１階を鉄平石貼、２階を木部現しとし、内部は広間を中心に食堂、居間、応接間を配す。漆喰塗と木部の対比が優美で、特に食堂天井の立体装飾は見事。平面計画から細部装飾まで稠密な設計の我が国チューダー住宅の傑作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014452"},{"id":"00002208","register_sub_id":"101","register_pk":"103198","name":"小田部鋳造主屋","kana":"こたべちゅうぞうしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町田45","lat":36.273838,"lng":140.096222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0056","desc":"西岡本店店舗と通りを隔てた向かいの敷地中央に建つ。現当主で３７代を数える格式ある鋳物師の居宅で，規模は桁行９間，梁行５間とし，入母屋造，桟瓦葺，平入に造る。内部は南半分を土間とし，北寄りに大黒柱を立てるなど農家と同様な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002208"},{"id":"00002210","register_sub_id":"101","register_pk":"103200","name":"小田部鋳造南土蔵","kana":"こたべちゅうぞうみなみどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町田45","lat":36.273701,"lng":140.09639,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0058","desc":"主屋の東方，北土蔵の南方に位置する。桁行４間半，梁行２間半規模，南北棟，切妻造，桟瓦葺，置屋根形式の平入２階建土蔵で，西面と南面に約４尺の庇を架け渡し，西面中央に戸口を設ける。もと文庫蔵と伝えられ，北土蔵に比べ丁寧な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002210"},{"id":"00002211","register_sub_id":"101","register_pk":"103201","name":"小田部鋳造門","kana":"こたべちゅうぞうもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町田45","lat":36.27386886,"lng":140.09592796,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造薬医門、間口3.0m","structure_material":"木造薬医門","registered":"2001.08.28(平成13.08.28)","register_no":"08 － 0059","desc":"敷地の西側を通る道路が屈曲する地点に建つ。現在は工場と倉庫に挟まれた位置に在り，主屋の土間部に通じる。間口約３ｍ，南北棟の１間１戸薬医門で，正面右手斜め前方に板塀，左手に通用口を開けた屋根付石塀を従える。鋳造所の格式がうかがわれる遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002211"},{"id":"00008095","register_sub_id":"101","register_pk":"132493","name":"坂入家住宅主屋","kana":"さかいりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県石岡市辻字山下179","lat":36.19005307,"lng":140.16958128,"geo_status":"db","era":"明治前期／明治24年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"08 － 0240","desc":"山裾の敷地に南面して建つ。木造平屋建、桁行２１ｍ梁間９．６ｍ、寄棟造茅葺、棟中央に桟瓦葺越屋根を付ける。土間を西側に、六間取で縁をまわす床上部を東側に配する。当地方の大規模農家の姿を伝え、トオシモノと呼ばれる軒付など茅葺屋根は見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008095"},{"id":"00001852","register_sub_id":"101","register_pk":"102842","name":"坂長本店石蔵","kana":"さかちょうほんてんいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県古河市中央町3-5742・5743他","lat":36.19254668,"lng":139.70428409,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造2階建、瓦葺、建築面積104㎡","structure_material":"石造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"08 － 0034","desc":"屋敷の端に位置する長大な２階建の石蔵。外壁は大谷石の切石積とし，１階各所に扉口を構え，扉口両脇柱及びまぐさに長大な一石の切石を用いる。屋根は切妻造，桟瓦葺とし，２階の妻壁に窓を設ける。北関東における石蔵の中でも大規模な部類に属す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001852"},{"id":"00001849","register_sub_id":"101","register_pk":"102839","name":"坂長本店主屋","kana":"さかちょうほんてんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県古河市中央町3-5742・5743他","lat":36.19265336,"lng":139.70410109,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積135㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"08 － 0031","desc":"旧古河城下大工町で江戸初期から両替商を始め，江戸末期頃から酒問屋を営んでいる商家で屋号を「坂長」と称する。主屋は，木造２階建で，座敷飾などの細工や意匠が優れた和風建築。店蔵及び袖蔵が移築されて屋敷の整備が行われた時期の再建と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001849"},{"id":"00001851","register_sub_id":"101","register_pk":"102841","name":"坂長本店中蔵","kana":"さかちょうほんてんなかぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県古河市中央町3-5742・5743他","lat":36.19250338,"lng":139.70418625,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"08 － 0033","desc":"屋敷地最奥，文庫蔵と石蔵の間に位置する２階建の土蔵。外壁は白漆喰塗り，屋根は切妻造，桟瓦葺とする。建築年代は明確でないが屋敷内の建築群の中で最も古いものと伝え，当家が両替商を営んでいた時期を偲ばせる。内部は改装して酒造関係設備を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001851"},{"id":"00001850","register_sub_id":"101","register_pk":"102840","name":"坂長本店文庫蔵（旧質蔵）","kana":"さかちょうほんてんぶんこぐら（きゅうしちぐら）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県古河市中央町3-5742・5743他","lat":36.192513,"lng":139.704102,"geo_status":"db","era":"安政5","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"08 － 0032","desc":"主屋の後方に位置する２階建の土蔵で，屋根は切妻造，桟瓦葺とする。外壁は白漆喰塗で，一部を黒漆喰塗とする。安政５年の墨書銘があり建築年代が明らかである。困窮者を救済するための「おたすけ普請」により建設されたと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001850"},{"id":"00003780","register_sub_id":"101","register_pk":"104770","name":"桜井家住宅主屋","kana":"さくらいけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁409","lat":36.27898,"lng":140.102692,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積135㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"08 － 0116","desc":"店舗の北方に建つ。寄棟造，桟瓦葺の平屋建で，東方に台所，西方に１０畳仏間と６畳洋間を配し，台所北方に浴室と釜場，仏間北方に１２畳の座敷を突出し，座敷の北西端には装飾的グリルを嵌めた便所を張り出す。隣地沿い西面は店舗と同様防火的な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003780"},{"id":"00003782","register_sub_id":"101","register_pk":"104772","name":"桜井家住宅新蔵","kana":"さくらいけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁409","lat":36.27906513,"lng":140.10292761,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"08 － 0118","desc":"西蔵の東方に南北棟で建つ。桁行４間梁間２間半規模，切妻造，桟瓦葺，平入の２階建土蔵で，西面に１間幅の土庇を差し掛ける。もと質蔵と伝えられ，外部を黒漆喰塗，妻面及び東面の腰を簓子下見張とする。破風板を付けた軒回りの造作にも特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003782"},{"id":"00003781","register_sub_id":"101","register_pk":"104771","name":"桜井家住宅西蔵","kana":"さくらいけじゅうたくにしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁409","lat":36.27913526,"lng":140.1027977,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"08 － 0117","desc":"主屋の北方に位置し，南北棟で建つ。桁行３間梁間２間規模，切妻造，桟瓦葺，妻入の２階建土蔵で，外部は白漆喰塗とし，正面の南妻面以外の３面を簓子下見で覆う。２階の南面と東面北寄りに庇付きの窓を開け，鉄製の観音開戸を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003781"},{"id":"00003505","register_sub_id":"101","register_pk":"104495","name":"佐藤家住宅表門","kana":"さとうけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁397","lat":36.27873993,"lng":140.10241931,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.5m","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0110","desc":"旧古城村の西端に位置し，かっての陣屋の裏通りに西面して建つ。本柱の内側に控柱を建て，妻面に懸魚付の破風板を付け，門両側に小規模な脇戸を設ける。本柱等の精巧な埋木細工も特色。堂々とした外観を有する薬医門で，歴史的街路景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003505"},{"id":"00002879","register_sub_id":"101","register_pk":"103869","name":"島家住宅主屋","kana":"しまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県東茨城郡城里町大字神古内字竹ノ内４８０","lat":36.46648625,"lng":140.32077614,"geo_status":"db","era":"江戸中期／江戸末期改造","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺、建築面積165㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"08 － 0073","desc":"桁行７間，梁間４間の「おもや」と，東南隅に馬屋を設けた桁行６間，梁間３間半の「かまや」から成る。分棟型民家の系統にあるとみなされる曲屋風の民家で，曲屋部「かまや」の南面屋根を兜造風に切り落とし出窓に格子を建てるなどの特色をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002879"},{"id":"00016479","register_sub_id":"101","register_pk":"574841","name":"下邑家住宅主屋","kana":"しもむらけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県つくば市栗原字台坪3470-2他","lat":36.132815,"lng":140.11623472,"geo_status":"db","era":"江戸後期／明治後期増築・改修、昭和57年・平成24年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺一部銅板葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"08 - 0326","desc":"市街地東部の農村集落に位置する旧家の住宅主屋。敷地の南西に南面して建つ、平屋建寄棟造鉄板葺で南面東端に式台玄関を設け、東・西・南の軒をせがい造とする。座敷は付書院の障子や欄間に繊細な組子を用い、広い式台玄関など格式を備えた大規模な主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016479"},{"id":"00016481","register_sub_id":"101","register_pk":"574843","name":"下邑家住宅北蔵","kana":"しもむらけじゅうたくきたぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市栗原字台坪3470-2他","lat":36.132815,"lng":140.11623472,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"08 - 0328","desc":"主屋の東に建ち、かつて質草を保管した蔵。西面して建つ土蔵造二階建切妻造妻入で置屋根形式の桟瓦葺とする。外壁は漆喰塗仕上、腰は下見板張とする。内部は各階板敷で小屋組は太い地棟に登梁を架け、壁は竪板張。西妻に鏝絵で屋号を掲げ丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016481"},{"id":"00016480","register_sub_id":"101","register_pk":"574842","name":"下邑家住宅米蔵","kana":"しもむらけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県つくば市栗原字台坪3470-2他","lat":36.132815,"lng":140.11623472,"geo_status":"db","era":"大正10年頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積106㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"08 - 0327","desc":"主屋の南に北面して建つ米蔵。二階建切妻造桟瓦葺で北・東に矩折の下屋を付す。外壁は真壁で黒漆喰塗仕上、腰は押縁下見板張とする。軸部は半間毎に通し柱を立て、小屋組は束を用いず梁を密に組み上げる。長大なマツの一丁材の下屋桁など豪壮なつくりの米蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016480"},{"id":"00016484","register_sub_id":"101","register_pk":"574846","name":"下邑家住宅外便所","kana":"しもむらけじゅうたくそとべんじょ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県つくば市栗原字台坪3470-2他","lat":36.132815,"lng":140.11623472,"geo_status":"db","era":"明治40年／昭和57年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"08 - 0331","desc":"長屋門の北に続き、通りに沿って位置する便所。東面して建つ平屋建切妻造平入桟瓦葺で、外壁は漆喰塗仕上、腰は押縁下見板張とする。内部は中央部に大便所、小便所、洗面所を並べ、両端室は土間の物置とする。旧家の生活の様相を伝える桁行長大な便所棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016484"},{"id":"00016483","register_sub_id":"101","register_pk":"574845","name":"下邑家住宅長屋門","kana":"しもむらけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市栗原字台坪3470-2他","lat":36.132815,"lng":140.11623472,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"08 - 0330","desc":"敷地西側の通りに面して建つ長屋門。平屋建切妻造平入桟瓦葺で、正面軒をせがい造とし、外壁は漆喰塗仕上、正面腰は海鼠壁仕上とする。中央門口の左右に物置と倉庫を配する。門口廻りにケヤキ材を用いた重厚なつくりの長屋門で地域の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016483"},{"id":"00016485","register_sub_id":"101","register_pk":"574847","name":"下邑家住宅塀","kana":"しもむらけじゅうたくへい","category":"住宅","subcategory":"その他工作物","type_guess":"塀","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市栗原字台坪3470-2","lat":36.132815,"lng":140.11623472,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、総延長44m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"08 - 0332","desc":"敷地西側の通りに面し、長屋門の両脇に延びる塀。三段の切石積基礎にのせた土台上に柱を立て、軒桁を腕木で支持し、屋根は桟瓦葺とする。壁は漆喰塗仕上、腰は外を押縁下見板張、内を竪板目板張。長屋門と連続し、屋敷正面を整え、歴史的な景観を形成する塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016485"},{"id":"00016482","register_sub_id":"101","register_pk":"574844","name":"下邑家住宅南蔵","kana":"しもむらけじゅうたくみなみぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県つくば市栗原字台坪3470-2他","lat":36.132815,"lng":140.11623472,"geo_status":"db","era":"大正13年頃／昭和後期改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積26㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"08 - 0329","desc":"主屋の東、北蔵と並び建つ道具蔵。木造二階建切妻造妻入桟瓦葺で正面に下屋を付し、外壁は真壁で漆喰塗仕上、腰は鉄板張とする。内部は各階板敷、小屋組は登梁形式で壁は竪板張。関東大震災後の再建と伝え、簡素なつくりながらも旧家の屋敷構えを伝える倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016482"},{"id":"00004694","register_sub_id":"101","register_pk":"105684","name":"鈴木家住宅表門","kana":"すずきけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁34","lat":36.27587114,"lng":140.10331628,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0179","desc":"真壁町の中心街上宿通りの東端に位置し，通りに北面する屋敷地北西部に東西棟で建つ。門口２．４ｍ規模，切妻造，桟瓦葺の１間１戸の薬医門で，前面の軒を出桁造とし，東西に袖塀を従え，西側に脇戸を設ける。上宿通りの歴史的景観を形成する要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004694"},{"id":"00002001","register_sub_id":"101","register_pk":"102991","name":"鈴木醸造長屋門","kana":"すずきじょうぞうながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町古城191","lat":36.27598719,"lng":140.1053438,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"08 － 0051","desc":"長屋門は主屋西面に建つ。寄棟造・桟瓦葺で，出桁造で深い軒をつくる。中央に内開き板戸を構え，左右は背面戸口付の部屋とする。外壁は腰を簓子下見板張，上部を白漆喰塗とし，正面右に格子窓を設ける。屋敷正面の構えとして，地域の景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002001"},{"id":"00004510","register_sub_id":"101","register_pk":"105500","name":"鈴木紡績主屋","kana":"すずきぼうせきしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字西の宮町1355","lat":36.304462,"lng":139.8754999,"geo_status":"db","era":"明治39／昭和8増築","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積136㎡","structure_material":"木造2階一部平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0170","desc":"見世蔵の南に接続する居宅部分。北半が寄棟造，桟瓦葺の平屋建，南半が入母屋造，桟瓦葺の二階建増築部である。北半１階は８畳と６畳の周囲に縁が巡る。起りのある切妻造玄関をもつ南半には，１階に１０畳と折上天井の洋室，２階に座敷１０畳と８畳を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004510"},{"id":"00002747","register_sub_id":"101","register_pk":"103737","name":"関根家住宅主屋","kana":"せきねけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁390","lat":36.27918343,"lng":140.10148646,"geo_status":"db","era":"明治8","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"08 － 0061","desc":"店舗の背面に接続し，角屋状に突出する。古くは別棟の住居があったので，ここは店舗と繋がる当初の客座敷と考えられる。桟瓦葺・平家建で６畳間２室と８畳間などからなる。開放的な縁の扱いや，丁寧なつくりの床や付書院などに近代和風の造形が現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002747"},{"id":"00004322","register_sub_id":"101","register_pk":"105312","name":"塚本家住宅主屋","kana":"つかもとけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁60","lat":36.27663331,"lng":140.10122297,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造2階建、瓦葺、建築面積147㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0152","desc":"敷地西側，見世蔵の奥に建つ。寄棟造，桟瓦葺の木造２階建で，棟を南北に置く。外壁は腰まで石積みとし，それより上を白漆喰で仕上げ，軒に鉢巻を回す。２階の座敷３室は創建当時の状態を良く残す。見世蔵，門などとともに広大な瓦葺屋根景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004322"},{"id":"00004323","register_sub_id":"101","register_pk":"105313","name":"塚本家住宅土蔵","kana":"つかもとけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁60","lat":36.27656911,"lng":140.10135304,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積80㎡","structure_material":"土蔵造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0153","desc":"敷地南側接道部分の東隅に建つ。切妻造，桟瓦葺，平入の２階建土蔵で，棟を南北に置き，正面（西面）には下屋を架ける。外壁は白漆喰で仕上げ，軒に鉢巻を回す。道路に面する妻壁２階部分に小窓を設け，見世蔵，門と並び，上宿通りの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004323"},{"id":"00004324","register_sub_id":"101","register_pk":"105314","name":"塚本家住宅門","kana":"つかもとけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁60","lat":36.27652079,"lng":140.10128317,"geo_status":"db","era":"明治40／昭和44移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0154","desc":"敷地南側接道部分のほぼ中央に建つ薬医門。切妻造，桟瓦葺で，東西に棟を置く。明治４０年に裏門として建てられ，昭和４４年の正門取壊しに伴い上宿通りに面する現在位置に移築された。見世蔵及び，土蔵前黒板塀と軒を連ね，通りの歴史的景観を形成する要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004324"},{"id":"00003369","register_sub_id":"101","register_pk":"104359","name":"土谷家住宅土蔵","kana":"つちやけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁272-1","lat":36.2794451,"lng":140.09639,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0091","desc":"天保４年の台風災害後のお助け普請という土蔵。木造２階建，桟瓦葺，切妻造，平入で，東面１階を扉口とする。街路に面した南妻面は２階に２つの縦長窓を設ける。基礎の石積，腰の海鼠壁，重厚な観音扉，垂木型を現した軒の塗籠など質の高いつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003369"},{"id":"00004702","register_sub_id":"101","register_pk":"105692","name":"出川家住宅石蔵","kana":"でがわけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁347","lat":36.27788438,"lng":140.10121193,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造２階建、瓦葺、建築面積35㎡","structure_material":"石造２階建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0187","desc":"主屋の南方に南北棟で建つ。桁行６．７ｍ梁間４．０ｍ規模，切妻造，桟瓦葺の２階建石蔵で，北妻面に土庇を差し掛けて戸口を開ける。石材は花崗岩で，壁厚は３２５ｍｍとし，桁行の外壁には江戸切り仕上げの石を積んだ丁寧なつくり。小屋組は和小屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004702"},{"id":"00004701","register_sub_id":"101","register_pk":"105691","name":"出川家住宅主屋","kana":"でがわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁347","lat":36.27811566,"lng":140.1012968,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積90㎡","structure_material":"木造2階一部平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0186","desc":"陣屋跡の北側に通じる仲町通りに北面して建つ。桁行４間梁行３間４尺，東西棟，入母屋造，桟瓦葺の木造２階建の背後に南北棟，寄棟造の木造平屋建が続く。正面は昭和２６年薬局開業のため改装されているが，下屋庇とせずに小庇を付けた住宅風のつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004701"},{"id":"00006300","register_sub_id":"101","register_pk":"107283","name":"照沼家住宅主屋","kana":"てるぬまけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県那珂郡東海村大字照沼字寺沼23","lat":36.4356,"lng":140.593475,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積250㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"08 － 0222","desc":"敷地中央に建つ，曲り屋形式の民家。建築面積２５０㎡，木造平屋建，茅葺。土間は桁行７間，梁間４間半と広大で，太い棟持柱が梁組を支える。床上部は７室からなり，東側の書院は数寄屋風の造作で，座敷構を備える。当地の豪農住宅の特徴をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006300"},{"id":"00000812","register_sub_id":"101","register_pk":"101802","name":"篆刻美術館裏蔵棟（旧平野家裏蔵棟）","kana":"てんこくびじゅつかんうらぐらとう（きゅうひらのけうらぐらとう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県古河市中央町二丁目5655-1他","lat":36.19455235,"lng":139.7028422,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造２階建，瓦葺，建築面積66㎡","structure_material":"石造２階建","registered":"1998.10.09(平成10.10.09)","register_no":"08 － 0005","desc":"表蔵棟の南にあって，中庭を挟んで建つ標準的な切妻造，２階建の石蔵。内部は１階が２室に区分されるが，２階は１室としキングポストの小屋組を見せる。表蔵とも展示棟として改修され，裏蔵の前後に事務棟や土庇が接続し，棟には明かり取りの越屋根が付く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000812"},{"id":"00000811","register_sub_id":"101","register_pk":"101801","name":"篆刻美術館表蔵棟（旧平野家表蔵棟）","kana":"てんこくびじゅつかんおもてぐらとう（きゅうひらのけおもてぐらとう）","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県古河市中央町二丁目5655-1他","lat":36.19470164,"lng":139.70288292,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造３階建，瓦葺，建築面積29㎡","structure_material":"石造３階建","registered":"1998.10.09(平成10.10.09)","register_no":"08 － 0004","desc":"大谷石を用いた三階建の小規模な蔵で，妻側に独特の意匠の開口部を設ける。商店街の象徴的な建物として知られ，内部は１階のみ本格的な洋間とする。道路拡幅のため，近年曳屋され展示館として再生され，３階部分は吹抜けとし小屋組を見せる等改修された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000811"},{"id":"00014319","register_sub_id":"101","register_pk":"511308","name":"富田家住宅主屋","kana":"とみたけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県笠間市大郷戸字内川378","lat":36.38751944,"lng":140.20286389,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積342㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"08 - 0317","desc":"石材産地の集落に所在する農家の主屋。正面東向きで座敷は庭に南面する。入母屋造桟瓦葺、軒を豪壮な出桁造とする。北側を広大な土間と居間、玄関座敷を介して南側に座敷を三室並べ、最奥は角屋座敷となる。笠間藩主家紋の釘隠や筬欄間など格式高い書院座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014319"},{"id":"00003373","register_sub_id":"101","register_pk":"104363","name":"中村家住宅主屋","kana":"なかむらけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁字新宿町433","lat":36.27978352,"lng":140.10079611,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積125㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0095","desc":"見世蔵背面に連続して建つ。木造平屋建，桟瓦葺で，居室部は南面が見世蔵に接続，北面が入母屋造になり，南東に台所，北西に部屋等を張り出す。大工は地元の増淵氏で，良材を丁寧に使いこなしている。当地域における店舗と居室の空間構成をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003373"},{"id":"00002748","register_sub_id":"101","register_pk":"103738","name":"中村家住宅主屋","kana":"なかむらやじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁391-1","lat":36.279053,"lng":140.1017,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"08 － 0062","desc":"広い屋敷地中心の西寄りに建つ。平家建で南北棟の切妻造・妻入になり，北・東・南に庇を廻し，北面に式台玄関を構える。もと接客用の座敷と伝え，Ｌ字型平面で最奥の１０畳間に本格的な床・棚・付書院を備える。簡素な外観ながら，質の高い書院造の建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002748"},{"id":"00002750","register_sub_id":"101","register_pk":"103740","name":"中村家住宅文庫蔵","kana":"なかむらやじゅうたくぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁391-1","lat":36.278923,"lng":140.101898,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造3階建、瓦葺、建築面積26㎡","structure_material":"土蔵造3階建","registered":"2002.06.25(平成14.06.25)","register_no":"08 － 0064","desc":"屋敷の東側ほぼ中央にあり，南北棟の切妻造・桟瓦葺で，西面南端に観音扉を設けて庇をつける。外壁は鉢巻から下を漆喰壁を下見板張で覆う。内部は各階の階高を低く押さえて３階建とするなど，規模は小さいが，丁寧なつくりに加え工夫を凝らした土蔵建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002750"},{"id":"00002751","register_sub_id":"101","register_pk":"103741","name":"中村家住宅薬医門及び塀","kana":"なかむらやじゅうたくやくいもんおよびへい","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁391-1","lat":36.27915095,"lng":140.10179935,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、門間口2.7m及び塀延長25m","structure_material":"木造","registered":"2002.06.25(平成14.06.25)","register_no":"08 － 0065","desc":"切妻造・桟瓦葺の薬医門と，その西に延びる延長約２５ｍの塀。薬医門は組物もなく簡素だが，両側に潜り戸のある袖塀をもつ。塀は漆喰壁の腰を縦板で覆った丁寧な形式ものである。広大な屋敷地北面を画するとともに，街路景観に欠かせない構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002751"},{"id":"00004115","register_sub_id":"101","register_pk":"105105","name":"西岡家住宅主屋","kana":"にしおかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字上宿町56-1","lat":36.2773051,"lng":140.10264614,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積108㎡","structure_material":"木造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0129","desc":"店舗の北側に接して東西棟で建つ。桁行９間半梁間２間半規模，寄棟造，桟瓦葺の木造２階建で，１階は帳場続きの８畳の東に６畳２室，西に床付き８畳と６畳を配し，２階は１０畳２室とする。外観簓子下見板張，開口部上部を漆喰塗とした伝統的和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004115"},{"id":"00004116","register_sub_id":"101","register_pk":"105106","name":"西岡家住宅土蔵","kana":"にしおかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字上宿町56-1","lat":36.27730424,"lng":140.10253842,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"08 － 0130","desc":"主屋の西方に南北棟で建つ。桁行５間梁間３間半規模，切妻造，桟瓦葺の平入２階建土蔵で，東面に庇を出して２戸口を設け，南妻面１階２階及び北妻面２階に庇付き観音開扉窓と，北妻面１階に小窓２箇所を開ける。店舗前庭を構成する主要素になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004116"},{"id":"00004759","register_sub_id":"101","register_pk":"105749","name":"沼尻家住宅蔵","kana":"ぬまじりけじゅうたくくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市金田38-1","lat":36.10229976,"lng":140.14161938,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0177","desc":"主屋の南方，米蔵の北西方に位置し，南北棟で建つ。桁行３間梁間２間規模，切妻造，桟瓦葺，妻入の木造２階建で，北妻面に下屋庇を差し掛けて戸口を開ける。１階を農具置き場，２階を文書庫とする。外部は米蔵と同様，真壁造で腰高の押縁下見板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004759"},{"id":"00004758","register_sub_id":"101","register_pk":"105748","name":"沼尻家住宅米蔵","kana":"ぬまじりけじゅうたくこめぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市金田38-1","lat":36.10227276,"lng":140.14178566,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0176","desc":"主屋の南方，屋敷地の南辺近くに位置し，南北棟で建つ。桁行３間半梁間２間半規模，切妻造，桟瓦葺，妻入の木造２階建で，北面に下屋庇を差し掛けて戸口を設ける。外壁は真壁造で，腰高く下見板を張る。内部を改装し，喫茶店として活用が図られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004758"},{"id":"00004757","register_sub_id":"101","register_pk":"105747","name":"沼尻家住宅主屋","kana":"ぬまじりけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県つくば市金田38-1","lat":36.10258493,"lng":140.14152659,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0175","desc":"金田村組頭役を務めた旧家。通りに南面する敷地の北寄り中央に東西棟で建つ。桁行１０間半梁間６間半規模，寄棟造，茅葺の平屋建で，西方を土間，東方を四間取の床上部とする。南側のヒロマとトコノマの正面南側に１間幅の入側をもつのが当地域民家の特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004757"},{"id":"00004760","register_sub_id":"101","register_pk":"105750","name":"沼尻家住宅長屋","kana":"ぬまじりけじゅうたくながや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"茨城県","address":"茨城県つくば市金田38-1","lat":36.10248748,"lng":140.14179524,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、瓦葺、建築面積53㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0178","desc":"主屋の南東方に位置し，南北棟で建つ。桁行６間梁間３間規模，切妻造，桟瓦葺の木造２階建で，西・北の２面に下屋庇を廻す。もと作業場として使用され，２階は蚕室として利用された。近代の屋敷構えを今に伝える建物。現在は衣料品店舗として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004760"},{"id":"00004329","register_sub_id":"101","register_pk":"105319","name":"根本医院門","kana":"ねもといいんもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁202","lat":36.27667531,"lng":140.10069604,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0159","desc":"敷地南端のほぼ中央に建つ高麗門で，東西に黒板の袖塀が付設し，うち東側袖塀に潜戸が付く。切妻造で，門，袖塀とも桟瓦葺とし，目地を漆喰で塗る。根本家が笠間藩の御殿医を勤めた時期の建設と考えられ，上宿通りの歴史的景観を形成する建造物のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004329"},{"id":"00004327","register_sub_id":"101","register_pk":"105317","name":"土生都家住宅主屋","kana":"はぶつけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁75-2","lat":36.276508,"lng":140.10045204,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積65㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0157","desc":"北側を接道する敷地の北東部に北面して建つ。桁行４間半梁間４間の木造２階建とし，南北棟の桟瓦葺寄棟屋根を置く。北側前面には入母屋造の玄関を張り出す。外壁は簓子下見板張とし，正面のみ壁面上部に漆喰塗を施す。比較的新しい時代の近代和風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004327"},{"id":"00004328","register_sub_id":"101","register_pk":"105318","name":"土生都家住宅門","kana":"はぶつけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁75-2","lat":36.27661659,"lng":140.1004821,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口2.1m、左右袖塀付","structure_material":"木造","registered":"2004.11.08(平成16.11.08)","register_no":"08 － 0158","desc":"敷地北端のほぼ中央に建つ高麗門で，東西に袖塀が付設し，うち西側袖塀に潜戸が付く。切妻造とし，門，袖塀とも瓦葺とする。門柱及び控柱に丸柱を用い，正面の?にも丸太材を使用する。主屋や斜向かいの根本医院門とともに，上宿通りの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004328"},{"id":"00004204","register_sub_id":"101","register_pk":"105194","name":"府中誉長屋門","kana":"ふちゅうほまれながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.18572528,"lng":140.27501448,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"08 － 0137","desc":"主屋の東北方に位置し，敷地北面街路に沿って東西棟で建つ。桁行約５間梁間７尺，切妻造，桟瓦葺の長屋門で，門口は１０尺幅，両脇に潜りを設け，花崗石を敷き詰める。門部の主要軸部は欅材を用いる。かって府中の玄関口であった幸町見付門を模したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004204"},{"id":"00004205","register_sub_id":"101","register_pk":"105195","name":"府中誉文庫蔵","kana":"ふちゅうほまれぶんこぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県石岡市国府5-9-32","lat":36.18573155,"lng":140.274887,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積29㎡","structure_material":"土蔵造3階建","registered":"2004.07.23(平成16.07.23)","register_no":"08 － 0138","desc":"主屋の北方に東西棟で建ち，主屋西北隅の蔵前座敷に戸口を開く。桁行３間半梁間２間半規模，切妻造，桟瓦葺の黒漆喰塗３階建土蔵で，東面２階３階に窓，西面に３段の水切を付ける。地棟墨書から建設年代と「棟梁廣原文次郎 左官山口朝之助」等が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004205"},{"id":"00008621","register_sub_id":"101","register_pk":"149342","name":"保坂家住宅主屋","kana":"ほさかけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県結城市大字結城字浦町135他","lat":36.30362271,"lng":139.8729145,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積140㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0241","desc":"通りに南面する敷地に建つ。木造平屋建、建築面積140㎡。Ｌ字型の棟になる寄棟造桟瓦葺で、下屋庇を付設する。西寄りの玄関の奥に6畳と8畳の座敷が南北に続き、玄関東には10畳座敷が設けられ、縁をまわす。庭園に面した穏やかな外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008621"},{"id":"00008622","register_sub_id":"101","register_pk":"149343","name":"保坂家住宅土蔵","kana":"ほさかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県結城市大字結城字浦町135他","lat":36.30356011,"lng":139.87302617,"geo_status":"db","era":"大正11年","year":1922,"year_source":"converted","year_min":1922,"year_max":1922,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"08 － 0242","desc":"主屋の東側に、板間を介して建つ。土蔵造2階建、桁行5.5ｍ梁間3.6ｍ、南北棟の切妻造妻入桟瓦葺。外壁は漆喰仕上げで、南妻の1階と2階開口部に、銅板葺庇を付け、掛子塗の両開戸を吊る。平屋の主屋東端に位置し、重厚な妻面を見せて、外観を引き締める","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008622"},{"id":"00003374","register_sub_id":"101","register_pk":"104364","name":"細谷家住宅主屋","kana":"ほそやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町飯塚44","lat":36.27894131,"lng":140.09618257,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積174㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0096","desc":"南面して建つ。木造平屋建，寄棟造，桟瓦葺で，北面には下屋を廻し，東面と北西隅に納戸等の附属部分を張り出す。たちの高いつくりで，側廻り小壁に入れたガラス窓，出桁造で疎垂木小舞打とした軒廻りなど，当地域における近代民家の造形をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003374"},{"id":"00003375","register_sub_id":"101","register_pk":"104365","name":"細谷家住宅長屋門","kana":"ほそやけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町飯塚44","lat":36.27890483,"lng":140.0959405,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0097","desc":"南面して建つ。木造平屋建，寄棟造，桟瓦葺で，北面には下屋を廻し，東面と北西隅に納戸等の附属部分を張り出す。たちの高いつくりで，側廻り小壁に入れたガラス窓，出桁造で疎垂木小舞打とした軒廻りなど，当地域における近代民家の造形をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003375"},{"id":"00003503","register_sub_id":"101","register_pk":"104493","name":"増渕家住宅主屋","kana":"ますぶちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁396","lat":36.27859904,"lng":140.10248442,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0108","desc":"店舗の背面に接続する。桁行４間半，梁間３間半規模で，寄棟造，桟瓦葺の木造平屋建とする。内部は３室の座敷からなり，南面及び東面に廊下を廻し，６畳間が店舗板ノ間，南面廊下が店舗土間と接続する。外装は簓子下見板張で，店舗と一体的な外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003503"},{"id":"00003504","register_sub_id":"101","register_pk":"104494","name":"増渕家住宅長屋門","kana":"ますぶちけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁396","lat":36.27857993,"lng":140.10234814,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"08 － 0109","desc":"店舗の南側に接続する。間口６．９ｍ規模の切妻造，桟瓦葺で，一軒疎垂木とする。門の両脇には小規模な潜戸を設け，上部を二重出桁とし，門南側を漆喰塗壁とする。小規模ながら，良質な欅材を用いた風格あるつくりとし，歴史的景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003504"},{"id":"00004703","register_sub_id":"101","register_pk":"105693","name":"増渕宥市家住宅表門","kana":"ますぶちひろいちけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁412","lat":36.27947676,"lng":140.10260404,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0188","desc":"桜井地区に至る通りに西面して建つ。門口２．７ｍ規模，切妻造，桟瓦葺の門で，親柱の内側に控柱を建て貫と梁で繋ぎ，親柱上の冠木に束を建てて棟木を支持し，腕木を出して軒桁を受ける形式をとる。棟門・薬医門・腕木門を折衷した独特のつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004703"},{"id":"00004704","register_sub_id":"101","register_pk":"105694","name":"増渕宥市家住宅土蔵","kana":"ますぶちひろいちけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁412","lat":36.27928752,"lng":140.10268004,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0189","desc":"屋敷地南方の東寄りに位置し，東西棟で建つ。桁行３間半梁間２間規模，切妻造，桟瓦葺，平入の２階建土蔵で，内部は１階を２室に分ける。北面中央に戸口を設け，２階東妻面に観音開きの防火戸を備えた窓を開ける。往時の屋敷構えの一端を伝える建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004704"},{"id":"00003367","register_sub_id":"101","register_pk":"104357","name":"間宮家住宅主屋","kana":"まみやけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県常陸大宮市高部3991","lat":36.66346079,"lng":140.30208045,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造2階一部3階建、瓦葺及び銅板葺、建築面積193㎡","structure_material":"木造2階一部3階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0089","desc":"伝統的な農家風の２階建和風棟と，その東に接続する３階建洋館からなる木造の和洋折衷住宅。洋館は通り側の東面１階に玄関ポーチを設け，３階を漆喰壁，他を下見板張とする。窓枠飾，玄関扉など本格的で，淡い緑色の外観は地域景観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003367"},{"id":"00003366","register_sub_id":"101","register_pk":"104356","name":"宮本家住宅大蔵","kana":"みやもとけじゅうたくおおぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市北条188","lat":36.1774109,"lng":140.093307,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0088","desc":"敷地東側のほぼ中央，西面して建つ南北棟の切妻造，平入，桟瓦葺で，桁行１１ｍ，梁間４．５ｍの規模を持つ土蔵。木造２階建，外壁は漆喰塗とし，北に連続して建つ新蔵と庇を共有し，正面には鳥居型窓枠付の２階窓を設けている。保存状態も良好である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003366"},{"id":"00003360","register_sub_id":"101","register_pk":"104350","name":"宮本家住宅居宅","kana":"みやもとけじゅうたくきょたく","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県つくば市北条188","lat":36.17757483,"lng":140.09313993,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積141㎡","structure_material":"木造平屋一部2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0082","desc":"店蔵の南側にあり，廊下で接続している。木造，１部２階建，南北棟の寄棟造，桟瓦葺で，西・南・東に下屋を廻し，外壁漆喰塗とする。変形した田の字型平面で，座敷などは南面に配し，南側を開放的につくる。店蔵と一体感をもって，屋敷中心部をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003360"},{"id":"00003365","register_sub_id":"101","register_pk":"104355","name":"宮本家住宅新蔵","kana":"みやもとけじゅうたくしんぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市北条188","lat":36.17748773,"lng":140.093323,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0087","desc":"敷地東側のほぼ中央にあり，文書等を収蔵している。西を正面とする東西棟の切妻造，妻入，桟瓦葺で，木造２階建，外壁は漆喰塗とし，南に連続して建つ大蔵と庇を共有する。正面には庇付の２階窓を設け，上部に円形漆喰飾をつけるなど，つくりも丁寧である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003365"},{"id":"00003362","register_sub_id":"101","register_pk":"104352","name":"宮本家住宅炊事場","kana":"みやもとけじゅうたくすいじば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県つくば市北条188","lat":36.17751848,"lng":140.093201,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0084","desc":"居宅の東面南側より東に連続している。いわゆる大規模な台所で，風呂や物置なども附属している。木造平屋建，東西棟で東が入母屋造，西が居宅に連なり，南と北に庇をつける。大規模屋敷の生活空間の様相を物語る施設で，居宅と一体となった建築構成を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003362"},{"id":"00003364","register_sub_id":"101","register_pk":"104354","name":"宮本家住宅炭・味噌小屋及び車庫","kana":"みやもとけじゅうたくすみ・みそごやおよびしゃこ","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"low","period":"明治","pref":"茨城県","address":"茨城県つくば市北条188","lat":36.177563,"lng":140.09334917,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵及び木造平屋一部2階建、瓦葺及び鉄板葺、建築面積31㎡","structure_material":"土蔵及び木造平屋一部2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0086","desc":"屋敷の北東隅，南北棟の細長い建物で，生活の一端を物語る施設。木造，１部２階建，切妻造，平入で，西面に庇をつける。北半が真壁造，桟瓦葺の炭・味噌小屋，南半が外壁下見板張，鉄板葺の車庫になる。北端は街路に妻壁を見せ，門との調和も図られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003364"},{"id":"00003361","register_sub_id":"101","register_pk":"104351","name":"宮本家住宅離れ","kana":"みやもとけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市北条188","lat":36.177418,"lng":140.093079,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0083","desc":"敷地西側中央，居宅の南方に廊下で接続している。木造平屋建，南北棟の寄棟造，桟瓦葺（軒先銅板葺）である。規模は小さいが，床・付書院のある座敷など３室構成で，東と南は縁を廻し，西は外壁簓子下見板張とする。数寄屋風意匠で纏められた瀟洒な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003361"},{"id":"00003363","register_sub_id":"101","register_pk":"104353","name":"宮本家住宅門","kana":"みやもとけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県つくば市北条188","lat":36.1776429,"lng":140.09333159,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.4m、塀付","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0085","desc":"門は街路に面して建つ店蔵の東方に建ち，両者の間に塀を設けて，屋敷正面の構えを整えている。１間１戸薬医門形式の門で，１軒疎垂木，切妻造，桟瓦葺の屋根を架ける。真壁造，漆喰塗の塀は腰を簓子下見板張とし，桟瓦葺の小屋根を腕木形式で受けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003363"},{"id":"00001864","register_sub_id":"101","register_pk":"102854","name":"三輪家住宅主屋","kana":"みわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町真壁229","lat":36.278355,"lng":140.098679,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0037","desc":"主屋は見世蔵の背面に接続して建つ。桁行４間・梁間３間，切妻造・平屋建で，見世蔵と一体的な土蔵造。見世蔵の１階帳場奥に６畳の居間，その奥に８畳の客間がある。客間は床・違い棚・付書院を備えた書院造風の端正な意匠となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001864"},{"id":"00004699","register_sub_id":"101","register_pk":"105689","name":"村上家住宅表門","kana":"むらかみけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字高上町232","lat":36.27818145,"lng":140.09789617,"geo_status":"db","era":"明治初期／明治35頃移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0184","desc":"屋敷地西辺のほぼ中央，主屋店舗棟の南方に位置する。門口２．７ｍ規模，南北棟，切妻造，桟瓦葺の１間１戸薬医門で，前後とも出桁造として軒天井を張り，両袖塀には潜り戸を開ける。村上本家からの移築と伝える本格的なつくりで，通りの景観で際立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004699"},{"id":"00004698","register_sub_id":"101","register_pk":"105688","name":"村上家住宅土蔵","kana":"むらかみけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁字高上町232","lat":36.27815376,"lng":140.09825504,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0183","desc":"離れの東方，屋敷地の東北隅に位置し，南北棟で建つ。桁行３間半梁間２間規模，切妻造，桟瓦葺，平入の２階建土蔵で，西面に土庇を差し掛け，観音開きの防火扉を吊りこんだ戸口を開ける。窓は２階南妻面の１箇所で，観音開きの防火戸を備えた丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004698"},{"id":"00004697","register_sub_id":"101","register_pk":"105687","name":"村上家住宅離れ","kana":"むらかみけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県桜川市真壁町真壁字高上町232","lat":36.2782139,"lng":140.09813304,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0182","desc":"主屋座敷棟の東側に東西棟で建ち，主屋とは渡り廊下で結ばれる。桁行３間半梁行２間半規模，寄棟造，桟瓦葺の木造平屋建で，南面に下屋を付ける。４畳半と床飾りをもつ６畳２室から成り，南面に半間幅の縁側を設ける。主屋背後の中庭を取り囲む要素のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004697"},{"id":"00004707","register_sub_id":"101","register_pk":"105697","name":"谷口家住宅主屋","kana":"やぐちけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町桜井373","lat":36.28101228,"lng":140.10442076,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造2階一部平屋建、瓦葺、建築面積178㎡","structure_material":"木造2階一部平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0192","desc":"南北の通りに面する店舗の背後に位置する。桁行６間半梁行５間半規模，東西棟，寄棟造，桟瓦葺，平入のつし２階建で，東方に東西棟，寄棟造の１０畳座敷を続ける。内部は店舗寄りの西方を土間とし，床上部は８畳４室を田の字型に並べる。材質や造作は上質。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004707"},{"id":"00004708","register_sub_id":"101","register_pk":"105698","name":"谷口家住宅離れ","kana":"やぐちけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"大正","pref":"茨城県","address":"茨城県桜川市真壁町桜井373","lat":36.28090376,"lng":140.10457204,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階一部平屋建、瓦葺、建築面積84㎡","structure_material":"木造2階一部平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0193","desc":"主屋座敷の東南方に位置する。６畳と３畳に縁を廻した西側の平屋建は東西棟の入母屋造につくり，その背後東側に桁行３間半梁行２間半，南北棟，入母屋造の２階屋を配置する。２階は１２畳規模の１室で，床・棚・平書院を備えた良質の大広間を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004708"},{"id":"00004706","register_sub_id":"101","register_pk":"105696","name":"谷口義衛家住宅土蔵","kana":"やぐちよしえけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町桜井1","lat":36.28038641,"lng":140.10360073,"geo_status":"db","era":"江戸末期／明治25頃移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"08 － 0191","desc":"長屋門物置の西方，主屋居住部の南方に位置し，東西棟で建つ。桁行３間梁間２間規模，切妻造，桟瓦葺，平入の２階建土蔵で，北面に１間幅の土庇を差し掛けて蔵前とする。戸口や２階東妻の窓に観音開きの防火戸を備える。小屋組は中引梁に登梁を渡した形式。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004706"},{"id":"00001870","register_sub_id":"101","register_pk":"102860","name":"谷田部家住宅長屋門","kana":"やたべけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町古城198-1","lat":36.27455038,"lng":140.10491359,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"08 － 0043","desc":"江戸初期より代々名主を努めた旧家。屋敷地西辺に建つ長屋門は桁行８間・梁間２間，寄棟造・もと茅葺で，南面と東面一部に下屋を廻す。平面は中央を内開扉構，北側を８畳座敷，南側を板敷物置とし，正面各間に小さな与力窓を設ける。保存状態も良好。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001870"},{"id":"00014232","register_sub_id":"101","register_pk":"509622","name":"谷中家住宅主屋","kana":"やなかけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城郡八千代町大字坪井字内海道87-1","lat":36.21234444,"lng":139.911775,"geo_status":"db","era":"明治30年／昭和初期改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、茅葺、建築面積176㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"08 - 0316","desc":"鬼怒川西岸の坪井に所在する農家の主屋。寄棟造茅葺平入の東西棟で軒をせがい造とし、軒付は新旧の苧殻を市松に配して意匠を凝らす。内部は東を土間、西を六間取として南に内縁を設け、北は下屋を付して三室を配す。大規模で地域の歴史的景観を形成する民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014232"},{"id":"00003371","register_sub_id":"101","register_pk":"104361","name":"山中家住宅土蔵","kana":"やまなかけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁308","lat":36.27896662,"lng":140.09873042,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積78㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0093","desc":"敷地の奥に建つ土蔵。木造２階建，東西棟の切妻造，平入，桟瓦葺で，北面１階には扉口を設けて庇を架ける。２階は東妻面に窓を設ける。大棟の高い棟積，水切を多用した漆喰塗の外壁，垂木型を現した塗籠の軒，庇両端の漆喰壁など，要所に工夫がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003371"},{"id":"00003370","register_sub_id":"101","register_pk":"104360","name":"山中家住宅長屋門","kana":"やまなかけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県桜川市真壁町真壁308","lat":36.279209,"lng":140.09886669,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"08 － 0092","desc":"敷地が接する北側の街路に平行して建つ。間口１３．５ｍの規模を持つ木造平屋建で，入母屋造，桟瓦葺とし，軒は出桁造で疎垂木を配る。中央部の門口は欅材で豪壮な構えをつくり，左右の部屋の正面は漆喰塗壁で腰を簓子下見板張とし，街路景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003370"},{"id":"00004505","register_sub_id":"101","register_pk":"105495","name":"結真紬主屋","kana":"ゆうしんつむぎしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"茨城県","address":"茨城県結城市大字結城字大町68-1","lat":36.30373714,"lng":139.8749928,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"08 － 0165","desc":"見世蔵の南背後に接続する住居部分。木造平屋建で，寄棟屋根を桟瓦葺とし，南側に瓦葺庇を付ける。内部は見世蔵との間に幅４尺の取合部を介して，１０畳座敷，８畳次の間など２列４室の居室を配す。座敷の南側は１間幅の広縁とし，ガラス障子越しに庭を望む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004505"},{"id":"00010738","register_sub_id":"101","register_pk":"201573","name":"和田家住宅延年楼","kana":"わだけじゅうたくえんねんろう","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県水戸市自由が丘4610-29","lat":36.383951,"lng":140.44146,"geo_status":"db","era":"天保6／昭和35・同53移築","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"08 ‐ 0273","desc":"切妻造桟瓦葺の平屋建、土庇銅板葺の茶亭。東より玄関、押入付五畳の待合、座敷飾を設ける書院を並べる。書院北に水屋を設けて、三畳と一畳台目の茶室を配する。二度移築されるも部材は概ね残している。年代が明確で、江戸末期茶室の造形と趣向をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010738"},{"id":"00012295","register_sub_id":"101","register_pk":"531619","name":"秋元家住宅土蔵","kana":"あきもとけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県流山市流山二丁目109-9","lat":35.85560278,"lng":139.89960833,"geo_status":"db","era":"江戸末期／明治後期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"12-0271","desc":"みりん醸造で栄えた流山本町界隈に建つ。もとは貴重品を納めた蔵と考えられる。切妻造桟瓦葺妻入で、半間ごとに柱を立て小屋を二重梁とし、出入口に観音扉を設けるなど堅牢につくる。市街化著しい流山中心部にあって、地域の歴史的景観を伝える貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012295"},{"id":"00014324","register_sub_id":"101","register_pk":"511313","name":"安藤家住宅稲荷社","kana":"あんどうけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県袖ケ浦市代宿字野口1037-1","lat":35.45699167,"lng":140.021,"geo_status":"db","era":"昭和初期頃","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期頃","structure":"木造平屋建、銅板葺、建築面積0.5㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"12 - 0321","desc":"主屋西の築山上に南面して建つ一間社流造の稲荷社。身舎正面に桟唐戸二枚を吊り、側背面を横板張とし、切目長押、内法長押を廻す。軒は一軒繁垂木、屋根を銅板葺とし、棟は成の高い箱棟風とした独特な造り。全体に簡素ながら敷地西側の景観をつくる稲荷社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014324"},{"id":"00014322","register_sub_id":"101","register_pk":"511311","name":"安藤家住宅主屋","kana":"あんどうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県袖ケ浦市代宿字野口1037-1","lat":35.45692222,"lng":140.02116389,"geo_status":"db","era":"江戸末期／昭和６０年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積187㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"12 - 0319","desc":"袖ケ浦市街地から北東の代宿に所在する農家。平屋建寄棟造平入鉄板仮葺（茅葺）で東面し、軒を出桁造とする。内部は北に土間、南に二列五室とし、下手は押板と仏壇を備えたチャノマ、上手は続き間座敷とする。東面二箇所に式台を付した上総の典型的な民家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014322"},{"id":"00014323","register_sub_id":"101","register_pk":"511312","name":"安藤家住宅土蔵","kana":"あんどうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県袖ケ浦市代宿字野口1037-1","lat":35.45677222,"lng":140.02124167,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積20㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"12 - 0320","desc":"主屋の南東に北面し、家財を収納する土蔵。二階建切妻造妻入で、屋根は置屋根形式の桟瓦葺。北に戸口を設け、南に窓を一箇所開ける。内部は１・２階とも一室で、北東隅に階段を配し、二階床中央に荷揚げ口を設ける。敷地南東の歴史的景観をつくる土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014323"},{"id":"00011879","register_sub_id":"101","register_pk":"211053","name":"飯沼本家主屋","kana":"いいぬまほんけしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県印旛郡酒々井町馬橋字場々106-1","lat":35.709328,"lng":140.271575,"geo_status":"db","era":"江戸中期／大正10年頃増築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋一部2階建、瓦葺、建築面積237㎡","structure_material":"木造平屋一部2階建","registered":"2017.10.27(平成29.10.27)","register_no":"12-237","desc":"台地上にある敷地後方の中央に東面する。もと茅葺で土間と二列六室からなり、ヒロマ奥にナンドを配し、ゲンカン、ナカノマ、オクノマは部屋境中央にも旧は柱が立つ県内民家の特徴を備えていて、大正期に二階や張出しの玄関を増築し、瓦葺の外観が整えられた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011879"},{"id":"00011880","register_sub_id":"101","register_pk":"211054","name":"飯沼本家離れ屋","kana":"いいぬまほんけはなれや","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県印旛郡酒々井町馬橋字場々106-1","lat":35.709165,"lng":140.271715,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"12-238","desc":"主屋南東に廊下で接続する。入母屋造、桟瓦葺で、一〇畳と八畳を並べ縁側を廻らし、南東隅に茶室を張り出す。一〇畳の座敷は、床の間、床脇、付書院を備え、良材を用いた端正な意匠で、茶室は皮付の曲がり材を用いて野趣を加味した意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011880"},{"id":"00011881","register_sub_id":"101","register_pk":"211055","name":"飯沼本家前蔵","kana":"いいぬまほんけまえぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県印旛郡酒々井町馬橋字場々106-1","lat":35.709212,"lng":140.271813,"geo_status":"db","era":"明治前期／昭和10年代改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積28㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"12-239","desc":"主屋南東方に北面する。桁行三間、梁間二間で、切妻造の置屋根形式で、正面に下屋庇を設ける。内部は一室で真壁とし、曲がり材を用いた豪壮な小屋を組む。外壁は、腰板張で上部漆喰塗で鉢巻を廻らし、二階正面に二所の窓を穿つ。旧家の屋敷構えを構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011881"},{"id":"00001177","register_sub_id":"101","register_pk":"102167","name":"石橋家住宅土蔵","kana":"いしばしけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県成田市久井崎215","lat":35.84864093,"lng":140.41113848,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建，瓦葺，建築面積40㎡","structure_material":"土蔵造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0019","desc":"東の蔵の西北方に位置する東西棟、瓦葺切妻屋根、平入の座敷蔵で、南面に入母屋造の玄関を付ける。置屋根形式で、軒の鉢巻部を黒漆喰塗りとする他、東妻の窓の庇を入母屋造、扇垂木、組物で造るなどして他の蔵との違いを際だたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001177"},{"id":"00001176","register_sub_id":"101","register_pk":"102166","name":"石橋家住宅東の蔵","kana":"いしばしけじゅうたくひがしのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県成田市久井崎215","lat":35.84856079,"lng":140.41117972,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建，瓦葺，建築面積30㎡","structure_material":"土蔵造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0018","desc":"門の北に位置する南北棟、瓦葺切妻屋根、平入の土蔵で、道路沿いに１個、南妻に観音開きの窓を設け、西面に下屋を架ける。南の蔵とほぼ同様の造りの米蔵であるが、軒の鉢巻き直下までを板貼りとするなどして変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001176"},{"id":"00001175","register_sub_id":"101","register_pk":"102165","name":"石橋家住宅南の蔵","kana":"いしばしけじゅうたくみなみのくら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県成田市久井崎215","lat":35.84844755,"lng":140.41107914,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建，瓦葺，建築面積31㎡","structure_material":"土蔵造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0017","desc":"門の南に位置する南北棟、瓦葺切妻屋根、平入の土蔵で、道路沿いに２個、南妻に１個の窓をとり、西面に下屋を架けて蔵前とする。東面と北面は腰を簓子下見板貼として門及び東の蔵を含めた道路沿いの景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001175"},{"id":"00001174","register_sub_id":"101","register_pk":"102164","name":"石橋家住宅門","kana":"いしばしけじゅうたくもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県成田市久井崎215","lat":35.84849828,"lng":140.41114179,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建，瓦葺，建築面積5.0㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0016","desc":"町内屈指の豪農の館の表門。左右に蔵を従え、南の蔵との間に通用口、東の蔵との間に袖塀を付けた立ちの高い薬医門で、本瓦葺の重厚な屋根を載せる。大棟や降棟の鬼瓦、留蓋瓦や「石」「橋」銘入りの鐙瓦などに当家の権勢振りが窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001174"},{"id":"00009906","register_sub_id":"101","register_pk":"196053","name":"磯角商店主屋","kana":"いそかくしょうてんしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県銚子市飯沼町186","lat":35.73318021,"lng":140.84037507,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積78㎡、塀付","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"12 － 0170","desc":"木造二階建の和風住宅の南面に、洋間の応接室を張出し、ガラスブロックの塀を設ける。和洋取り混ぜた構成で、内装材にはラワンなど種々の材木を使う。二階には舟底状の折上天井を張る座敷を配し、随所に鯛の彫刻を施すなど、港町にふさわしい意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009906"},{"id":"00012503","register_sub_id":"101","register_pk":"367798","name":"伊藤家住宅井戸上屋","kana":"いとうけじゅうたくいどうわや","category":"住宅","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県柏市増尾四丁目1383","lat":35.835472,"lng":139.983551,"geo_status":"geocoded","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、茅葺、面積1.8㎡","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"12 － 0277","desc":"牛小屋の南隣に建つ。切妻造茅葺で、角柱を内転びに立て、内法貫と桁で軸部を固める。中央にコンクリート製の円筒井戸枠を置き、南側に隅切長方形の洗場を連ねる。簡素ながら生活空間に欠かせない附属建物で、伝統的な農家の屋敷構えの構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012503"},{"id":"00012500","register_sub_id":"101","register_pk":"367795","name":"伊藤家住宅隠居屋","kana":"いとうけじゅうたくいんきょや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県柏市増尾四丁目1383","lat":35.835472,"lng":139.983551,"geo_status":"geocoded","era":"明治前期／昭和前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"12 － 0274","desc":"主屋の東南方に西面して建つ。寄棟造茅葺で正面の軒を切上げて出桁造とし、正背両面に下屋、背面南端に角屋を出す。内部は三室を並べ、居住空間の南間は床を高く張る。中央と北間は作業場で、小屋裏を蚕室とする。伝統的な農家の屋敷構えの構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012500"},{"id":"00012502","register_sub_id":"101","register_pk":"367797","name":"伊藤家住宅牛小屋","kana":"いとうけじゅうたくうしごや","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県柏市増尾四丁目1383","lat":35.835472,"lng":139.983551,"geo_status":"geocoded","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"12 － 0276","desc":"主屋の東北方に西面して建つ。寄棟造茅葺で、西南北三面を出桁造とし、東南二面に下屋を設ける。外壁は荒壁仕上で、空気抜きに壁上部の一部を開放する。内部は後方を間仕切り、左右に牛房を設ける。伝統的な農家の屋敷構えの一角をなす附属建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012502"},{"id":"00013355","register_sub_id":"101","register_pk":"368443","name":"伊東家住宅主屋","kana":"いとうけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県山武郡芝山町小池1000","lat":35.69353611,"lng":140.41513333,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積219㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"12 － 0305","desc":"芝山町南部、旧街道に東面する敷地の中央北寄りに南面して建つ。木造平屋建、桁行八間半、梁間五間で、正面に下屋を付し、中央を玄関とする。内部は南東を土間、他を床上とし、北西に主座敷を置く。急勾配の桟瓦葺き屋根は、茅葺からの過渡的様相を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013355"},{"id":"00012498","register_sub_id":"101","register_pk":"367793","name":"伊藤家住宅主屋","kana":"いとうけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県柏市増尾四丁目1383","lat":35.835472,"lng":139.983551,"geo_status":"geocoded","era":"江戸後期／昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"12 － 0272","desc":"手賀沼南方の台地上にある農家で、主屋は東面して建つ。寄棟造茅葺で、四周を出桁造とし、正面南端に玄関を付して屋根を葺下ろす。北に土間、土間沿いの表に18畳の広間、南に三室を並べ奥を座敷とする。敷地中央にあって伝統的な屋敷構えの核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012498"},{"id":"00012501","register_sub_id":"101","register_pk":"367796","name":"伊藤家住宅土蔵","kana":"いとうけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県柏市増尾四丁目1383","lat":35.835472,"lng":139.983551,"geo_status":"geocoded","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積27㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"12 － 0275","desc":"隠居屋の西側に建つ農具収納用の蔵。東西棟の切妻造、二階建で、北面中央に戸口を開き、下屋を設ける。外壁は真壁造で、側面の腰を石積風にする。内部は板敷で、太めの通し柱を半間毎に立てて頑丈につくる。伝統的な農家の屋敷構えを構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012501"},{"id":"00012499","register_sub_id":"101","register_pk":"367794","name":"伊藤家住宅離れ","kana":"いとうけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県柏市増尾四丁目1383","lat":35.835472,"lng":139.983551,"geo_status":"geocoded","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積32㎡","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"12 － 0273","desc":"主屋の南側面後方に建ち、渡廊下で主屋に接続する客座敷。入母屋造桟瓦葺の総二階建で、外壁を下見板張とする。上下階に座敷一室を設け、一階は南西二面に大きく出窓を取り、北面に座敷飾を備える。随所に近代の趣向をみせ、充実した接客空間を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012499"},{"id":"00012879","register_sub_id":"101","register_pk":"367987","name":"上原家住宅石蔵","kana":"うえはらけじゅうたくいしぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市桐ケ作字前山18","lat":36.05369444,"lng":139.81555556,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"石造平屋建、瓦葺、建築面積33㎡","structure_material":"石造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"12 － 292","desc":"敷地西辺の北寄りに東面して建つ。切妻造桟瓦葺、大谷石造の平屋建で、正面中央に戸口を設け、両妻に高窓を穿ち、軒に鉢巻二段を廻す。内部は一室で一部前土間の板敷とし、小屋は合掌組である。下総地方農家の屋敷構えにおける近代の流行を伝える附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012879"},{"id":"00012880","register_sub_id":"101","register_pk":"367988","name":"上原家住宅表門","kana":"うえはらけじゅうたくおもてもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市桐ケ作字前山18-2","lat":36.05342222,"lng":139.81556667,"geo_status":"db","era":"明治中期／平成25年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.9m、脇戸付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"12 － 293","desc":"敷地南辺の中央に南面して建つ一間薬医門。総欅造、切妻造桟瓦葺で、西脇に潜戸を付す。親柱と冠木に大断面の五平材を用い、正面は軒桁を出梁上の肘木で受け、鏡天井を張り、梁上に彫刻板を入れる。明治期の戸長役場にふさわしい豪壮な表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012880"},{"id":"00012877","register_sub_id":"101","register_pk":"367985","name":"上原家住宅書院","kana":"うえはらけじゅうたくしょいん","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市桐ケ作字前山18","lat":36.05349167,"lng":139.81585556,"geo_status":"db","era":"明治中期／平成5年移築・改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"12 － 290","desc":"利根川と江戸川に挟まれた田園地帯の集落のもと名主宅。書院は敷地後方の主屋東面に接続して建つ寄棟造桟瓦葺の平屋建で、南面下屋の西端に玄関を設ける。内部は続き間の座敷で、高い天井や床と仏壇を前後に配した奥行1間の座敷飾が上層農家の格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012877"},{"id":"00012878","register_sub_id":"101","register_pk":"367986","name":"上原家住宅土蔵","kana":"うえはらけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県野田市桐ケ作字前山18","lat":36.0536,"lng":139.81548889,"geo_status":"db","era":"明治中期／平成4年移築・改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"12 － 291","desc":"敷地西辺の中ほどに東面して建つ。切妻造桟瓦葺、土蔵造二階建で、基礎は大谷石を五段に積み、軸部は柱を半間毎に立てて三段に梁をかけ渡す。内部は一階床を高く張り、壁縦板張とする。堅牢な構造や良材を用いた仕上が、上層農家の土蔵のつくりを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012878"},{"id":"00001166","register_sub_id":"101","register_pk":"102156","name":"内野家住宅洋館","kana":"うちのけじゅうたくようかん","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県銚子市長山町2034","lat":35.76955288,"lng":140.71786242,"geo_status":"db","era":"大正初期／昭和12移築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造２階建，瓦葺，建築面積124㎡","structure_material":"木造２階建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0008","desc":"東京麹町に所在した医院宅を現在地に移築し改造したもの。南の庭に向けてベイウインドウ状の張出しを設け、階下を吹放ちとしてテラス風に造る。外観は昭和初期の意匠が支配的であるが、内部インテリアは階段室を含め大正期の雰囲気をよく留めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001166"},{"id":"00015151","register_sub_id":"101","register_pk":"530575","name":"榎本家住宅稲荷社","kana":"えのもとけじゅうたくいなりしゃ","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"千葉県","address":"千葉県我孫子市布佐字下町3051-3","lat":35.85114722,"lng":140.13941111,"geo_status":"db","era":"昭和33年頃","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"12 - 0333","desc":"離れの西に位置する小社。基壇上に東面して建つ、一間社流造銅板葺。身舎は土台上に角柱を立て、腰長押、腰貫、内法長押で固め、柱頂は組物介さず桁・梁を受ける。庇柱は角柱で几帳面を取り、身舎柱と海老虹梁で繋ぐ。装飾抑えつつ丁寧なつくりの稲荷社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015151"},{"id":"00015146","register_sub_id":"101","register_pk":"530570","name":"榎本家住宅主屋","kana":"えのもとけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県我孫子市布佐字下町3051-3","lat":35.85113611,"lng":140.13970556,"geo_status":"db","era":"昭和前期／昭和33年頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積56㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"12 - 0328","desc":"利根川西岸の堤防沿いに位置する旧家の主屋。二階建寄棟造桟瓦葺の東西棟で南西に入母屋造玄関を付す。各階続きの座敷を配して南庭を望み、二階西室の床は床框に唐木を用いるなど凝ったつくり。軒を出桁で持出し、風格ある外観が旧家の屋敷景観の中核を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015146"},{"id":"00015149","register_sub_id":"101","register_pk":"530573","name":"榎本家住宅釜場","kana":"えのもとけじゅうたくかまば","category":"住宅","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県我孫子市布佐字下町3051-3","lat":35.85127222,"lng":140.13958333,"geo_status":"db","era":"昭和前期／昭和33年頃改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"12 - 0331","desc":"主屋の北東に位置する釜場。平屋建切妻造鉄板葺の東西棟で、正面屋根を葺き降ろして吹き放ちの下屋とし、棟中央に煙出を設ける。内部は東西２室とし東室は土間で上部は天井を張らず、二重梁の和小屋を現す。別棟の釜場として貴重で、敷地北の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015149"},{"id":"00015148","register_sub_id":"101","register_pk":"530572","name":"榎本家住宅北土蔵","kana":"えのもとけじゅうたくきたどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県我孫子市布佐字下町3051-3","lat":35.85121667,"lng":140.13951389,"geo_status":"db","era":"明治17年／昭和33年頃移築、平成23年改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"12 - 0330","desc":"離れの北に位置する家財蔵。土蔵造二階建切妻造桟瓦葺の東西棟で、外壁表面にコンクリートを廻らす。内部は各階板敷の一室とし、南西に階段を設け、二階上部は二重梁を架けて束立の和小屋を現し、厚板を流して屋根とする。掛子塗扉など上質な仕上とする土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015148"},{"id":"00015150","register_sub_id":"101","register_pk":"530574","name":"榎本家住宅正門","kana":"えのもとけじゅうたくせいもん","category":"住宅","subcategory":"その他工作物","type_guess":"門","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県我孫子市布佐字下町3051-3","lat":35.85095833,"lng":140.13967222,"geo_status":"db","era":"昭和前期／昭和33年頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"12 - 0332","desc":"通りから引込み南面して建つ表門。切妻造桟瓦葺、一間薬医門で、両脇に桟瓦葺板塀を付す。軸部木太く、ケヤキの良材を用い、冠木と控柱頭貫上に渡した三筋の梁で軒桁を支持する。大棟や降棟を高く積み、影盛とした豪壮な外観が旧家の風格ある表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015150"},{"id":"00015147","register_sub_id":"101","register_pk":"530571","name":"榎本家住宅離れ","kana":"えのもとけじゅうたくはなれ","category":"住宅","subcategory":"建築物","type_guess":"茶室・離れ","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県我孫子市布佐字下町3051-3","lat":35.85114444,"lng":140.13953333,"geo_status":"db","era":"明治中期／昭和33年頃移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"12 - 0329","desc":"主屋の西側に建つ離れ座敷。平屋建寄棟造桟瓦葺の東西棟で、南東端で主屋と接続する。内部は二室続きの座敷とし、西・南に縁を廻らす。西室は北に床を構え、西脇に付書院を備える。鶴・亀の釘隠や室境に飾る波と水鳥の透彫り欄間など華やかなつくりの離れ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015147"},{"id":"00013777","register_sub_id":"101","register_pk":"507692","name":"及川家住宅主屋","kana":"おいかわけじゅうたくおもや","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県匝瑳市飯塚字谷1263他","lat":35.73503056,"lng":140.55750556,"geo_status":"db","era":"江戸末期／明治前期・昭和50年頃・平成3年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積160㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"12 － 0308","desc":"沿岸部丘陵地に位置し、敷地奥に南面して建つ。寄棟造瓦形鉄板葺で、鉄板の下に茅葺を残し、軒を出桁造とする。東を土間とし、西の床上部は二列五室を配し、北西を床付の奥の間とし、西辺に広縁を付す。食違型の間取などに下総の上層農家の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013777"},{"id":"00013778","register_sub_id":"101","register_pk":"507693","name":"及川家住宅土蔵","kana":"おいかわけじゅうたくどぞう","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県匝瑳市飯塚字谷1263他","lat":35.73488611,"lng":140.55743056,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2021.06.24(令和3.06.24)","register_no":"12 － 0309","desc":"敷地北西に東面して建つ土蔵。二階建切妻造平入で桟瓦葺の置屋根を載せる。正面に桟瓦葺の下屋を設け、他は鉄板葺庇を廻らす。外壁は白漆喰塗に腰を黒漆喰塗とする。内部は一、二階とも一室で、小屋は登梁と和小屋の梁を交互に架ける。敷地景観の一角を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013778"},{"id":"00012505","register_sub_id":"101","register_pk":"367800","name":"大多和家住宅穀蔵","kana":"おおたわけじゅうたくこくぐら","category":"住宅","subcategory":"建築物","type_guess":"土蔵","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県長生郡白子町関字山中3881","lat":35.45071,"lng":140.360764,"geo_status":"geocoded","era":"江戸末期／平成26年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積50㎡","structure_material":"土蔵造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"12 － 0279","desc":"敷地の前面、長屋門の東側に並んで建つ。南北棟の寄棟造桟瓦葺で、四周を出桁造の一軒とする。北面中央に戸口を開き、外壁は漆喰塗で腰壁下見板張とする。内部は板敷に壁縦板張として小屋組を現す。長屋門と同じく名主屋敷の風格ある表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012505"},{"id":"00012504","register_sub_id":"101","register_pk":"367799","name":"大多和家住宅主屋","kana":"おおたわけじゅうたくしゅおく","category":"住宅","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県長生郡白子町関字山中3881","lat":35.45071,"lng":140.360764,"geo_status":"geocoded","era":"江戸末期／昭和40年頃増築、平成26年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（金属板仮葺）、建築面積273㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"12 － 0278","desc":"九十九里平野中ほどにある集落の名主宅で、主屋は敷地中央に南面して建つ。寄棟造茅葺(鉄板仮葺)。東に土間、土間沿いの表に広間を配し、西端を続き間として正面に入母屋玄関を出し、奥に座敷を設ける。伝統的な民家の特色を備え、集落景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012504"},{"id":"00012506","register_sub_id":"101","register_pk":"367801","name":"大多和家住宅長屋門","kana":"おおたわけじゅうたくながやもん","category":"住宅","subcategory":"建築物","type_guess":"門","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県長生郡白子町関字山中3881","lat":35.45071,"lng":140.360764,"geo_status":"geocoded","era":"江戸末期／平成26年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（金属板仮葺）、建築面積99㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"12 － 0280","desc":"敷地の前面中央に南面して建つ。東西棟の寄棟造鉄板葺で、四周を出桁造の一軒とし、背面に下屋を設け、中央間を門口とする。左右の室は北面に出入口を設け、床を板敷、根太天井として小屋裏を物置とする。豪壮な表門で、風格ある表構えの核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012506"}];
